window.BIOMASTER.MCQ_CELLBIO = [{"id":"MCQ-CB-001","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tế bào","q":"Bơm ion $Na^+/K^+$-ATPase trên màng sinh chất của tế bào động vật hoạt động theo nguyên tắc nào trong mỗi chu kỳ thủy phân 1 phân tử ATP?","opts":["Bơm $3\\text{ }Na^+$ vào trong và $2\\text{ }K^+$ ra ngoài tế bào.","Khuếch tán thụ động $3\\text{ }Na^+$ và $2\\text{ }K^+$ cùng chiều gradient nồng độ.","Bơm $2\\text{ }Na^+$ ra ngoài và $3\\text{ }K^+$ vào trong tế bào.","Bơm $3\\text{ }Na^+$ ra ngoài và $2\\text{ }K^+$ vào trong tế bào."],"ans":3,"exp":"Bơm $Na^+/K^+$-ATPase tiêu tốn 1 ATP để đẩy $3\\text{ }Na^+$ ra khỏi tế bào và đưa $2\\text{ }K^+$ vào trong tế bào, duy trì điện thế nghỉ."},{"id":"MCQ-CB-002","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tế bào","q":"Phân tử nào sau đây có thể khuếch tán trực tiếp qua lớp kép phospholipid của màng sinh chất nhanh nhất mà không cần kênh protein?","opts":["Hormone Insulin.","Khí $O_2, CO_2$ và hormone Testosterone.","Ion $Na^+$ và $K^+$.","Phân tử Glucose ($C_6H_{12}O_6$)."],"ans":1,"exp":"Các chất khí không phân cực ($O_2, CO_2$) và phân tử steroid kị nước (Testosterone) đi qua lớp kép phospholipid trực tiếp."},{"id":"MCQ-CB-003","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tế bào","q":"Bào quan nào sau đây có mặt ở tế bào thực vật bậc cao nhưng KHÔNG có ở tế bào động vật?","opts":["Ribosome và màng sinh chất.","Bộ máy Golgi và lưới nội chất.","Ti thể và Peroxisome.","Lục lạp và không bào trung tâm lớn."],"ans":3,"exp":"Lục lạp và không bào trung tâm lớn là đặc trưng của tế bào thực vật."},{"id":"MCQ-CB-004","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hóa sinh","q":"Liên kết hóa học chủ yếu giúp duy trì cấu trúc bậc hai ($\\alpha$-helix và $\\beta$-pleated sheet) của phân tử protein là:","opts":["Liên kết cộng hóa trị disulfide ($-S-S-$).","Liên kết kị nước giữa các gốc R.","Liên kết Hydrogen giữa các nhóm $-CO-$ và $-NH-$ của khung polypeptide.","Liên kết phosphodiester."],"ans":2,"exp":"Cấu trúc bậc 2 của protein được giữ vững nhờ liên kết Hydrogen giữa nguyên tử O của nhóm $-C=O$ và nguyên tử H của nhóm $-N-H$ trên khung polypeptide."},{"id":"MCQ-CB-005","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hô hấp TB","q":"Trong quá trình hô hấp hiếu khí ở tế bào nhân thực, giai đoạn Đường phân (Glycolysis) diễn ra ở đâu và tạo ra bao nhiêu ATP thực tế (net ATP) từ 1 phân tử Glucose?","opts":["Bào tương (tế bào chất); tạo $2\\text{ ATP}$ (thu được $4\\text{ ATP}$, tiêu tốn $2\\text{ ATP}$ hoạt hóa).","Màng trong ti thể; tạo $32\\text{ ATP}$.","Chất nền ti thể; tạo $2\\text{ ATP}$.","Bào tương; tạo $4\\text{ ATP}$ thực tế."],"ans":0,"exp":"Đường phân diễn ra ở bào tương, tiêu tốn $2\\text{ ATP}$ đầu tư và thu về $4\\text{ ATP}$, lãi ròng $2\\text{ ATP}$ và $2\\text{ NADH}$."},{"id":"MCQ-CB-006","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Thẩm thấu","q":"Khi ngâm tế bào hồng cầu người và tế bào biểu bì hành tím vào nước cất tinh khiết (môi trường nhược trương), hiện tượng gì xảy ra?","opts":["Cả hai tế bào đều bị vỡ tan.","Hồng cầu trương nước và vỡ (tan máu), còn tế bào hành tím trương nước nhưng không vỡ nhờ có thành cellulose.","Cả hai tế bào đều co nguyên sinh.","Hồng cầu co lại, tế bào hành tím vỡ ra."],"ans":1,"exp":"Tế bào hồng cầu không có thành tế bào nên hút nước và vỡ; tế bào thực vật có thành cellulose cứng chắc tạo áp suất trương ($\\Psi_p$) ngăn nước tiếp tục đi vào."},{"id":"MCQ-CB-007","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vi sinh vật","q":"Thành tế bào của vi khuẩn (Eubacteria) được cấu tạo chủ yếu từ hợp chất hóa học nào sau đây (là đích tác động của kháng sinh Penicillin và enzyme Lysozyme)?","opts":["Cellulose.","Cholesterol.","Chitin.","Peptidoglycan (Murein)."],"ans":3,"exp":"Thành tế bào vi khuẩn cấu tạo từ Peptidoglycan. Penicillin ức chế enzyme tạo cầu nối peptide của Peptidoglycan, còn Lysozyme cắt liên kết glycoside giữa các đường NAG - NAM."},{"id":"MCQ-CB-008","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Động học Enzyme","q":"Cho 3 enzyme $E_1, E_2, E_3$ cùng xúc tác cho cơ chất $S$ với hằng số Michaelis ($K_m$) lần lượt là $0.02\\text{ mM}$, $0.5\\text{ mM}$ và $2.0\\text{ mM}$. Phát biểu nào đúng?","opts":["Thêm chất ức chế cạnh tranh vào $E_1$ làm $K_{m1}$ giảm.","$K_m$ tỉ lệ thuận với nồng độ enzyme.","Enzyme $E_1$ có ái lực với cơ chất $S$ cao nhất và đạt $\\frac{1}{2}V_{\\max}$ ở nồng độ cơ chất thấp nhất.","Enzyme $E_3$ có ái lực với cơ chất $S$ cao nhất."],"ans":2,"exp":"$K_m$ càng nhỏ thì ái lực của enzyme với cơ chất càng cao $\\Rightarrow E_1$ ($0.02\\text{ mM}$) có ái lực mạnh nhất."},{"id":"MCQ-CB-009","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Động học Enzyme","q":"Khi bổ sung một chất ức chế X vào phản ứng enzyme, người ta thấy $V_{\\max}$ giảm đi một nửa nhưng hằng số $K_m$ không thay đổi. Chất X thuộc loại nào?","opts":["Chất ức chế cạnh tranh.","Chất ức chế không cạnh tranh.","Cơ chất tương đồng.","Chất hoạt hóa dị lập thể."],"ans":1,"exp":"Chất ức chế không cạnh tranh gắn vào vùng dị lập thể nên không ảnh hưởng đến việc gắn cơ chất ($K_m$ không đổi) nhưng làm giảm lượng enzyme hoạt động ($V_{\\max}$ giảm)."},{"id":"MCQ-CB-010","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Truyền tin TB","q":"Trong con đường truyền tin của hormone Adrenaline (Epinephrine) tại tế bào gan qua thụ thể bắt cặp G-protein (GPCR), phân tử nào đóng vai trò là chất truyền tin thứ hai?","opts":["AMP vòng (cAMP).","Adenylyl cyclase.","Thụ thể Tyrosine kinase (RTK).","Protein kinase A (PKA)."],"ans":0,"exp":"Adrenaline gắn vào GPCR $\\rightarrow$ hoạt hóa G-protein $\\rightarrow$ hoạt hóa enzyme Adenylyl cyclase biến đổi ATP thành cAMP (chất truyền tin thứ hai)."},{"id":"MCQ-CB-011","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Bào quan","q":"Đánh dấu phóng xạ amino acid Leucine ($^3\\text{H}$-Leucine) trong môi trường nuôi cấy tế bào tuyến tụy đang tiết hormone Insulin. Trình tự xuất hiện dấu phóng xạ trong các cấu trúc nội bào là:","opts":["Lưới nội chất trơn $\\rightarrow$ Bộ máy Golgi $\\rightarrow$ Lysosome $\\rightarrow$ Màng sinh chất.","Ribosome tự do $\\rightarrow$ Nhân $\\rightarrow$ Ti thể $\\rightarrow$ Màng sinh chất.","Ribosome trên lưới nội chất hạt $\\rightarrow$ Túi tiết $\\rightarrow$ Bộ máy Golgi $\\rightarrow$ Túi tiết xuất bào qua màng sinh chất.","Bộ máy Golgi $\\rightarrow$ Lưới nội chất hạt $\\rightarrow$ Màng sinh chất."],"ans":2,"exp":"Insulin là protein tiết ngoại bào nên được tổng hợp tại Ribosome gắn trên lưới nội chất hạt (RER) $\\rightarrow$ túi vận chuyển sang Bộ máy Golgi chế biến $\\rightarrow$ túi tiết xuất bào."},{"id":"MCQ-CB-012","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Bộ khung xương TB","q":"Thuốc Colchicine và các thuốc điều trị ung thư như Vinblastine ngăn cản sự trùng hợp của cấu trúc nào dẫn đến không hình thành được thoi phân bào?","opts":["Lưới nội chất trơn.","Vi sợi Actin.","Vi ống (Microtubules - cấu tạo từ protein Tubulin).","Sợi trung gian (Intermediate filaments)."],"ans":2,"exp":"Thoi phân bào được cấu tạo từ các vi ống (tubulin). Colchicine/Vinblastine ngăn trùng hợp vi ống nên khóa phân bào ở kỳ giữa."},{"id":"MCQ-CB-013","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Peroxisome","q":"Bào quan Peroxisome ở tế bào gan và hạt cây có dầu chứa enzyme đặc trưng nào giúp phân giải độc tố Hydrogen peroxide ($H_2O_2$) thành nước và $O_2$?","opts":["Catalase.","RuBisCO.","Pepsinogen.","Hydrolase acid."],"ans":0,"exp":"Peroxisome chứa enzyme Catalase phân giải nhanh $2H_2O_2 \\rightarrow 2H_2O + O_2$ để bảo vệ tế bào khỏi gốc tự do."},{"id":"MCQ-CB-014","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Lên men vs Hô hấp","q":"Khi tế bào cơ xương người hoạt động tối đa trong điều kiện thiếu $O_2$, Pyruvate được chuyển hóa thành Lactate nhờ enzyme Lactate dehydrogenase. Mục đích sinh học quan trọng nhất của bước chuyển hóa Pyruvate thành Lactate là gì?","opts":["Để dự trữ năng lượng lâu dài trong cơ.","Để tái sinh coenzyme $NAD^+$ từ $NADH$, giúp giai đoạn Đường phân có thể tiếp tục diễn ra tạo $2\\text{ ATP}$.","Để trực tiếp tạo thêm $2\\text{ ATP}$ ở bước này.","Để giải phóng khí $CO_2$ làm tăng pH máu."],"ans":1,"exp":"Quá trình khử Pyruvate thành Lactate không tạo ra ATP, nhưng giúp oxy hóa $NADH \\rightarrow NAD^+$ để cung cấp nguyên liệu $NAD^+$ duy trì phản ứng Đường phân."},{"id":"MCQ-CB-015","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hô hấp Ti thể - Đề HSG Tỉnh","q":"Một chất độc làm thủng màng trong ti thể khiến ion $H^+$ đi qua tự do (như chất 2,4-DNP). Hiện tượng nào sau đây sẽ xảy ra ở tế bào bị nhiễm chất này?","opts":["Cả tốc độ tiêu thụ $O_2$ và tốc độ tổng hợp ATP đều tăng gấp đôi.","Tiêu thụ $O_2$ tăng vọt, phân giải Glucose tăng mạnh, tổng hợp ATP giảm nghiêm trọng và thân nhiệt tăng cao.","Ngừng tiêu thụ $O_2$, ngừng tổng hợp ATP và nhiệt độ cơ thể giảm.","Chuỗi truyền điện tử bị khóa tại phức hợp IV."],"ans":1,"exp":"2,4-DNP là chất phá ghép làm triệt tiêu gradient $H^+$ qua màng trong ti thể $\\rightarrow$ ngừng tạo ATP, chuỗi truyền $e^-$ chạy tối đa làm tiêu thụ $O_2$ và tỏa nhiệt tăng vọt."},{"id":"MCQ-CB-016","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hô hấp Ti thể - Đề HSG Tỉnh","q":"Nếu ti thể bị nhiễm độc chất Rotenone (khóa phức hợp I của chuỗi truyền điện tử), việc bổ sung chất nào sau đây vẫn giúp ti thể tiếp tục tổng hợp được ATP?","opts":["Succinate (hoặc $FADH_2$).","Malate.","Cyanide ($CN^-$).","Pyruvate."],"ans":0,"exp":"Succinate đi vào phức hợp II (tạo $FADH_2$) chuyển $e^-$ qua Ubiquinone tới phức hợp III và IV, bỏ qua phức hợp I đang bị Rotenone khóa."},{"id":"MCQ-CB-017","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Độc tố Dịch tả - Đề HSG Tỉnh","q":"Độc tố vi khuẩn tả (Cholera toxin) làm biến đổi hóa học tiểu phần $\\alpha$ của G-protein ($G_s$) ở tế bào biểu mô ruột non khiến nó mất khả năng thủy phân GTP thành GDP. Hậu quả trực tiếp là gì?","opts":["Enzyme Adenylyl cyclase bị bất hoạt hoàn toàn, nồng độ cAMP bằng 0.","Kênh $Na^+/K^+$ ngừng hoạt động làm tế bào ruột trương vỡ.","Tăng hấp thu nước từ lòng ruột vào máu.","G-protein luôn ở trạng thái hoạt hóa liên tục $\\rightarrow$ cAMP tăng vọt $\\rightarrow$ mở kênh $Cl^-$ (CFTR) bơm ồ ạt $Cl^-, Na^+$ và nước vào lòng ruột gây tiêu chảy cấp."],"ans":3,"exp":"Khi $G_s$ không thủy phân được GTP, nó duy trì trạng thái hoạt hóa liên tục $\\rightarrow$ kích thích Adenylyl cyclase sản xuất cAMP không ngừng $\\rightarrow$ PKA mở kênh CFTR tiết $Cl^-$ và kéo theo $Na^+, H_2O$ ra lòng ruột."},{"id":"MCQ-CB-018","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hóa thẩm Lục lạp vs Ti thể - Đề HSG Tỉnh","q":"Khi chiếu sáng lục lạp nguyên vẹn, sự thay đổi độ pH giữa xoang Thylakoid và chất nền Stroma diễn ra như thế nào để tổng hợp ATP?","opts":["$H^+$ được bơm vào xoang Thylakoid làm pH xoang Thylakoid giảm thấp ($\\approx 5$), còn pH chất nền Stroma tăng lên ($\\approx 8$).","Độ pH ở hai bên màng Thylakoid luôn bằng nhau ($pH = 7$).","$H^+$ được bơm từ xoang Thylakoid ra Stroma làm Stroma có $pH \\approx 5$, Thylakoid có $pH \\approx 8$.","ATP được tổng hợp bên trong lòng xoang Thylakoid."],"ans":0,"exp":"Trong pha sáng, $H^+$ tập trung cao ở xoang Thylakoid ($pH \\approx 5$) và thấp ở Stroma ($pH \\approx 8$, nơi hoạt hóa enzyme RuBisCO). $H^+$ khuếch tán từ xoang Thylakoid ra Stroma qua $CF_0CF_1$-ATP synthase để tổng hợp ATP tại Stroma."},{"id":"MCQ-CB-019","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Apoptosis - Đề HSG Tỉnh","q":"Trong con đường chết tế bào theo chương trình (Apoptosis) nội sinh, sự kiện giải phóng protein nào từ xoang gian màng ti thể ra bào tương sẽ trực tiếp kích hoạt dòng thác enzyme Caspase (Caspase-9 $\\rightarrow$ Caspase-3)?","opts":["Ubiquinone (Coenzyme Q).","Cytochrome c.","Catalase.","ATP synthase."],"ans":1,"exp":"Khi có tín hiệu Apoptosis nội sinh, protein Bax/Bak tạo lỗ trên màng ngoài ti thể giải phóng Cytochrome c ra bào tương, kết hợp với Apaf-1 tạo phức hợp Apoptosome hoạt hóa Caspase-9."},{"id":"MCQ-CB-020","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thí nghiệm Jagendorf - Đề HSG Tỉnh","q":"Thylakoid cô lập được ngâm trong dung dịch đệm $pH = 4$ trong tối cho đến khi cân bằng, sau đó chuyển nhanh sang dung dịch đệm $pH = 8$ có sẵn ADP và $P_i$ (vẫn đặt hoàn toàn trong tối). Kết quả thu được là gì?","opts":["Không có ATP nào được tạo ra vì không có ánh sáng.","ATP được tổng hợp mạnh mẽ trong tối nhờ chênh lệch $\\Delta pH$ nhân tạo ($H^+$ tràn từ lòng Thylakoid $pH=4$ ra môi trường $pH=8$).","$NADP^+$ bị khử thành NADPH.","Nước bị quang phân ly tạo $O_2$ trong tối."],"ans":1,"exp":"Thí nghiệm kinh điển của André Jagendorf chứng minh thuyết Hóa thẩm: Chỉ cần có chênh lệch gradient $H^+$ qua màng ($pH_{\\text{trong}} = 4 < pH_{\\text{ngoài}} = 8$) là ATP synthase tổng hợp được ATP mà không cần ánh sáng."},{"id":"MCQ-CB-021","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Điều hòa Đường phân PFK-1 - Đề HSG Tỉnh","q":"Enzyme Phosphofructokinase-1 (PFK-1) là điểm kiểm soát quan trọng nhất của quá trình Đường phân. Cặp phân tử nào sau đây đóng vai trò là chất ức chế dị lập thể và chất hoạt hóa dị lập thể đối với PFK-1?","opts":["Chất ức chế: AMP, ADP; Chất hoạt hóa: ATP, Citrate.","Chất ức chế: Insulin; Chất hoạt hóa: Glucagon.","Chất ức chế: ATP (nồng độ cao) và Citrate; Chất hoạt hóa: AMP và ADP.","Chất ức chế: Glucose; Chất hoạt hóa: NADH."],"ans":2,"exp":"Khi tế bào dư thừa năng lượng (ATP và Citrate cao), chúng gắn vào vùng dị lập thể để ức chế PFK-1. Khi tế bào thiếu năng lượng (AMP và ADP tăng cao), chúng hoạt hóa mạnh PFK-1 để đẩy nhanh đường phân."},{"id":"MCQ-CB-022","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thí nghiệm FRAP Màng sinh chất - Đề HSG Tỉnh","q":"Trong kỹ thuật phục hồi huỳnh quang sau tẩy màu (FRAP) để nghiên cứu tính động của protein màng, nếu một loại protein màng sau khi bị tia laser tẩy màu mà vùng tẩy màu KHÔNG phục hồi lại độ phát sáng huỳnh quang theo thời gian thì nguyên nhân hợp lý nhất là gì?","opts":["Protein đó đã được neo giữ cố định vào bộ khung xương tế bào (cytoskeleton) hoặc chất nền ngoại bào (ECM) nên không thể khuếch tán ngang.","Protein đó có kích thước quá nhỏ.","Nhiệt độ thí nghiệm là $37^\\circ\\text{C}$ quá cao.","Màng sinh chất ở vùng đó không có lớp kép phospholipid."],"ans":0,"exp":"Nếu protein màng tự do khuếch tán ngang, các protein gắn huỳnh quang xung quanh sẽ tràn vào vùng bị tẩy màu. Nếu vùng đó không phục hồi huỳnh quang, chứng tỏ protein đó bị neo chặt vào khung xương tế bào (như sợi actin/spectrin) hoặc ECM."},{"id":"MCQ-CB-023","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Thành phần hóa học tế bào","q":"Đặc tính nào của phân tử nước giúp điều hòa nhiệt độ cơ thể sinh vật và môi trường nước trên Trái Đất ổn định trước các biến động nhiệt đột ngột?","opts":["Khối lượng phân tử nhỏ và không phân cực.","Tỉ trọng của nước đá lớn hơn nước lỏng ở $0^\\circ\\text{C}$.","Khả năng tạo liên kết ion bền vững với lipid.","Nhiệt dung riêng cao và nhiệt bay hơi lớn nhờ mạng lưới liên kết Hydrogen."],"ans":3,"exp":"Nhờ các liên kết Hydrogen giữa các phân tử nước phân cực, cần rất nhiều nhiệt lượng để phá vỡ liên kết trước khi tăng động năng phân tử, tạo ra nhiệt dung riêng cao."},{"id":"MCQ-CB-024","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Thành phần hóa học tế bào","q":"Các nguyên tố hóa học nào chiếm khoảng $96\\%$ khối lượng cơ thể sống và đóng vai trò cấu tạo nên hầu hết các đại phân tử hữu cơ?","opts":["$\\text{C, H, O, N}$.","$\\text{C, H, P, S}$.","$\\text{Fe, Zn, Cu, I}$.","$\\text{Na, K, Ca, Cl}$."],"ans":0,"exp":"Bốn nguyên tố đa lượng chủ yếu cấu tạo nên chất sống là Carbon ($C$), Hydrogen ($H$), Oxygen ($O$) và Nitrogen ($N$)."},{"id":"MCQ-CB-025","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Thành phần hóa học tế bào","q":"Thiếu nguyên tố vi lượng Iodine ($\\text{I}$) trong khẩu phần ăn kéo dài ở người sẽ dẫn đến hậu quả trực tiếp nào sau đây?","opts":["Mất cân bằng áp suất thẩm thấu gây co giật cơ.","Giảm tổng hợp Hemoglobin trong hồng cầu gây thiếu máu nhược sắc.","Tuyến giáp không tổng hợp đủ hormone Thyroxine, gây bệnh bướu cổ và đần độn ở trẻ.","Xương và răng trở nên giòn dễ gãy do thiếu chất khoáng."],"ans":2,"exp":"Iodine là thành phần bắt buộc để cấu tạo hormone Thyroxine ($T_4$) và Triiodothyronine ($T_3$) của tuyến giáp."},{"id":"MCQ-CB-026","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Carbohydrate","q":"Loại polysaccharide nào sau đây đóng vai trò dự trữ năng lượng chủ yếu trong tế bào gan và cơ của động vật?","opts":["Cellulose.","Tinh bột (Amylose).","Glycogen.","Chitin."],"ans":2,"exp":"Động vật dự trữ glucose dưới dạng Glycogen (mạch phân nhánh dày đặc) tại gan và cơ xương; thực vật dự trữ dưới dạng tinh bột."},{"id":"MCQ-CB-027","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Carbohydrate","q":"Đơn phân cấu tạo nên phân tử đường đôi Sucrose (đường mía) gồm hai phân tử đường đơn nào liên kết với nhau?","opts":["$\\beta$-Glucose và $\\beta$-Glucose.","Glucose và Galactose.","$\\alpha$-Glucose và $\\alpha$-Glucose.","$\\alpha$-Glucose và Fructose."],"ans":3,"exp":"Sucrose được cấu tạo từ 1 gốc Glucose và 1 gốc Fructose liên kết qua liên kết glycoside; Lactose gồm Glucose + Galactose; Maltose gồm 2 Glucose."},{"id":"MCQ-CB-028","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Carbohydrate","q":"Tại sao động vật ăn cỏ như trâu, bò lại tiêu hóa được chất xơ (Cellulose) trong thực vật dù hệ gen của chúng không mã hóa enzyme Cellulase?","opts":["Nhờ hệ vi sinh vật cộng sinh trong dạ cỏ (hoặc manh tràng) tiết enzyme Cellulase thủy phân Cellulose.","Nhờ răng hàm nghiền nát biến Cellulose thành Glucose tự do.","Nhờ dịch vị dạ dày có nồng độ HCl rất cao tự bẻ gãy liên kết $\\beta$-1,4-glycoside.","Nhờ tuyến tụy của động vật nhai lại tiết ra Amylase biến tính."],"ans":0,"exp":"Động vật không có enzyme Cellulase, nhưng vi khuẩn và nguyên sinh vật cộng sinh trong dạ dày 4 ngăn (hoặc manh tràng ở ngựa, thỏ) tiết Cellulase phân giải chất xơ."},{"id":"MCQ-CB-029","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Lipid","q":"Trong cấu tạo phân tử Phospholipid tạo nên lớp kép màng sinh chất, thành phần nào mang tính ưa nước hướng ra phía môi trường nước?","opts":["Hai đuôi acid béo hydrocarbon dài không phân cực.","Vòng sterol kỵ nước nằm ở giữa màng.","Đầu chứa nhóm Phosphate phân cực gắn với Glycerol.","Các chuỗi oligosaccharide của glycoprotein."],"ans":2,"exp":"Phospholipid là phân tử lưỡng tính: đầu phosphate phân cực ưa nước quay ra hai bề mặt màng, còn hai đuôi acid béo kỵ nước quay vào trong lõi màng."},{"id":"MCQ-CB-030","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Lipid","q":"Chất nào sau đây thuộc nhóm Lipid có cấu trúc vòng sterol, là tiền chất tổng hợp hormone sinh dục (Testosterone, Estrogen) và muối mật?","opts":["Sáp (Wax).","Triglyceride (mỡ trung tính).","Phosphatidylcholine.","Cholesterol."],"ans":3,"exp":"Cholesterol là steroid quan trọng ở động vật, vừa tham gia cấu tạo màng sinh chất vừa là tiền chất của vitamin D, muối mật và hormone steroid."},{"id":"MCQ-CB-031","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Protein","q":"Liên kết hóa học nối trực tiếp giữa các đơn phân amino acid để tạo thành chuỗi polypeptide sơ cấp là loại liên kết nào?","opts":["Liên kết Hydrogen.","Liên kết Peptide (cộng hóa trị hình thành qua phản ứng trùng ngưng loại $H_2O$).","Liên kết Phosphodiester.","Liên kết Disulfide ($-S-S-$)."],"ans":1,"exp":"Nhóm carboxyl ($-COOH$) của amino acid trước kết hợp với nhóm amino ($-NH_2$) của amino acid sau, giải phóng 1 phân tử $H_2O$ tạo liên kết peptide ($-CO-NH-$)."},{"id":"MCQ-CB-032","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Protein","q":"Khi đun nóng lòng trắng trứng (albumin) hoặc cho chanh vào sữa tươi, protein bị vón cục và mất chức năng sinh học. Hiện tượng này gọi là gì?","opts":["Sự tổng hợp protein bậc 4.","Sự trùng hợp protein tạo sợi fibrin.","Sự biến tính protein (phá vỡ cấu trúc không gian bậc 2, 3, 4 nhưng giữ nguyên trình tự bậc 1).","Sự thủy phân hoàn toàn chuỗi polypeptide thành amino acid tự do."],"ans":2,"exp":"Nhiệt độ cao hoặc pH khắc nghiệt phá vỡ các liên kết yếu (H, ion, kỵ nước) duy trì cấu trúc không gian của protein gây biến tính."},{"id":"MCQ-CB-033","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nucleic acid","q":"Điểm khác biệt cơ bản về thành phần đường pentose và base nitơ giữa DNA và RNA là gì?","opts":["DNA chứa đường Ribose và base Uracil (U); RNA chứa đường Deoxyribose và base Thymine (T).","DNA có nhóm phosphate còn RNA không có nhóm phosphate.","DNA chỉ chứa Adenine và Guanine; RNA chỉ chứa Cytosine và Uracil.","DNA chứa đường Deoxyribose và base Thymine (T); RNA chứa đường Ribose và base Uracil (U)."],"ans":3,"exp":"Đường của DNA là Deoxyribose ($C_5H_{10}O_4$) và có Thymine; đường của RNA là Ribose ($C_5H_{10}O_5$) và thay Thymine bằng Uracil."},{"id":"MCQ-CB-034","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc tế bào nhân sơ","q":"Đặc điểm nào sau đây chỉ có ở tế bào nhân sơ (vi khuẩn) mà KHÔNG có ở tế bào nhân thực?","opts":["Vật chất di truyền nằm ở vùng nhân chưa có màng bao bọc và chỉ có ribosome loại 70S.","Có vật chất di truyền là phân tử DNA mạch kép thẳng liên kết chặt với Histone.","Có bộ máy Golgi và lưới nội chất phát triển.","Có màng sinh chất cấu tạo từ lớp kép phospholipid."],"ans":0,"exp":"Tế bào nhân sơ không có màng nhân, không có bào quan có màng bao bọc (trừ màng sinh chất), DNA vòng trần và ribosome 70S."},{"id":"MCQ-CB-035","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc tế bào nhân thực","q":"Bào quan nào được ví như 'nhà máy điện' của tế bào nhân thực vì là nơi tổng hợp phần lớn ATP qua chu trình Krebs và chuỗi truyền electron?","opts":["Lysosome.","Trung thể.","Ti thể.","Bộ máy Golgi."],"ans":2,"exp":"Ti thể thực hiện hô hấp hiếu khí (oxy hóa pyruvate, chu trình Krebs ở chất nền và chuỗi truyền $e^-$ hóa thẩm ở màng trong) tạo nguồn ATP chủ yếu cho tế bào."},{"id":"MCQ-CB-036","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc tế bào nhân thực","q":"Trong tế bào nhân thực, cấu trúc nào trong nhân là nơi tập trung rRNA và lắp ráp các tiểu phần của Ribosome?","opts":["Không bào.","Nhân con (hạch nhân - Nucleolus).","Màng nhân ngoài.","Lưới nội chất trơn."],"ans":1,"exp":"Nhân con (hạch nhân) chứa các gen rRNA đang phiên mã mạnh để lắp ráp tiểu phần lớn và nhỏ của ribosome trước khi xuất ra tế bào chất."},{"id":"MCQ-CB-037","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc tế bào nhân thực","q":"Bào quan nào chịu trách nhiệm tổng hợp lipid, chuyển hóa carbohydrate và giải độc rượu, thuốc trong tế bào gan?","opts":["Lưới nội chất trơn (SER).","Trung thể.","Lưới nội chất hạt (RER).","Nhân con."],"ans":0,"exp":"Tế bào gan có hệ thống lưới nội chất trơn (SER) phát triển mạnh chứa các enzyme giải độc (như cytochrome P450) và tổng hợp lipid."},{"id":"MCQ-CB-038","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc tế bào nhân thực","q":"Trong quá trình biến thái từ nòng nọc thành ếch, đuôi nòng nọc tiêu biến dần nhờ hoạt động tự thực và phân hủy của bào quan nào?","opts":["Lysosome.","Lục lạp.","Không bào co bóp.","Peroxisome."],"ans":0,"exp":"Lysosome chứa các enzyme thủy phân hoạt động trong môi trường acid giúp tiêu hóa các bào quan già cỗi và mô thoái hóa theo chương trình (như đuôi nòng nọc)."},{"id":"MCQ-CB-039","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vận chuyển qua màng","q":"Sự hấp thụ lại phần lớn Glucose tại tế bào biểu mô ống lượn gần của thận chống lại gradient nồng độ nhờ cặp đôi với dòng ion $Na^+$ đi vào theo gradient được gọi là cơ chế gì?","opts":["Khuếch tán tăng cường qua kênh Aquaporin.","Khuếch tán đơn giản qua lớp kép phospholipid.","Vận chuyển chủ động thứ phát (đồng vận chuyển $Na^+$-Glucose).","Ẩm bào không chọn lọc."],"ans":2,"exp":"Kênh đồng vận chuyển SGLT sử dụng năng lượng từ thế năng điện hóa của dòng $Na^+$ (do bơm $Na^+/K^+$-ATPase duy trì) để kéo Glucose ngược chiều nồng độ vào tế bào."},{"id":"MCQ-CB-040","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vận chuyển qua màng","q":"Khi đại thực bào (bạch cầu) nuốt trọn một con vi khuẩn kích thước lớn bằng cách vươn các chân giả bao lấy vi khuẩn rồi đóng kín thành túi nội bào, quá trình này gọi là gì?","opts":["Xuất bào (Exocytosis).","Thẩm thấu (Osmosis).","Ẩm bào (Pinocytosis).","Thực bào (Phagocytosis)."],"ans":3,"exp":"Thực bào là hình thức nhập bào các phần tử rắn lớn (vi khuẩn, mảnh vụn tế bào) nhờ màng sinh chất biến dạng tạo chân giả."},{"id":"MCQ-CB-041","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Thẩm thấu","q":"Khi nhỏ vài giọt dung dịch muối $NaCl$ ưu trương ($5\\%$) lên lá thài lài tía đang quan sát dưới kính hiển vi, hiện tượng gì sẽ xảy ra với tế bào biểu bì lá?","opts":["Nước tràn vào tế bào làm tế bào trương phồng và nổ tung.","Nước thoát ra khỏi không bào làm màng sinh chất tách dần khỏi thành tế bào (co nguyên sinh).","Không có sự thay đổi nào về thể tích chất nguyên sinh.","Thành cellulose co rúm lại hoàn toàn và biến mất."],"ans":1,"exp":"Trong môi trường ưu trương, nước di chuyển từ nơi có thế nước cao (bên trong tế bào) ra ngoài khiến khối tế bào chất co lại và tách khỏi thành cellulose."},{"id":"MCQ-CB-042","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Enzyme","q":"Vai trò cốt lõi của enzyme trong mọi phản ứng sinh hóa của cơ thể sống là gì?","opts":["Cung cấp năng lượng tự do $\\Delta G$ để biến phản ứng thu năng thành tỏa năng.","Bị tiêu hao vĩnh viễn sau mỗi chu kỳ xúc tác tạo sản phẩm.","Làm thay đổi hằng số cân bằng hóa học $K_{eq}$ của phản ứng.","Làm giảm năng lượng hoạt hóa ($E_a$) của phản ứng, giúp phản ứng xảy ra nhanh ở nhiệt độ sinh lý."],"ans":3,"exp":"Enzyme là chất xúc tác sinh học làm hạ thấp hàng rào năng lượng hoạt hóa ($E_a$), không làm thay đổi $\\Delta G$ của phản ứng và được tái sinh nguyên vẹn sau phản ứng."},{"id":"MCQ-CB-043","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Enzyme","q":"Enzyme Pepsin hoạt động trong dạ dày người có độ pH tối ưu vào khoảng giá trị nào?","opts":["$pH \\approx 7.0 - 7.4$.","$pH \\approx 1.5 - 2.0$.","$pH \\approx 11.0$.","$pH \\approx 8.5 - 9.0$."],"ans":1,"exp":"Pepsin là protease của dịch vị dạ dày, thích nghi với môi trường acid mạnh của HCl ($pH \\approx 2$). Khi xuống ruột non ($pH \\approx 8$), Pepsin bị bất hoạt."},{"id":"MCQ-CB-044","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Enzyme","q":"Tại sao khi bị sốt rất cao kéo dài trên $41^\\circ\\text{C}$, cơ thể người có nguy cơ tử vong do rối loạn chuyển hóa nghiêm trọng?","opts":["Nhiệt độ cao làm DNA tách hẳn thành hai mạch đơn vĩnh viễn ở $41^\\circ\\text{C}$.","Nhiệt độ cao làm nước trong máu đóng băng.","Nhiệt độ cao làm phá vỡ cấu trúc không gian của nhiều enzyme thiết yếu trong não và cơ quan nội tạng (biến tính).","Nhiệt độ cao làm tăng ái lực quá mức của enzyme với cơ chất."],"ans":2,"exp":"Đa số enzyme ở người có nhiệt độ tối ưu khoảng $37^\\circ\\text{C}$; vượt quá $40-42^\\circ\\text{C}$ sẽ làm enzyme biến tính và mất hoạt tính xúc tác."},{"id":"MCQ-CB-045","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Chuyển hóa năng lượng","q":"Phân tử ATP (Adenosine triphosphate) giải phóng năng lượng trực tiếp cho các hoạt động sống nhờ sự thủy phân liên kết nào?","opts":["Liên kết ester giữa đường ribose và nhóm phosphate thứ nhất.","Liên kết glycoside giữa đường ribose và base adenine.","Liên kết cộng hóa trị giữa các nguyên tử carbon trong vòng purine.","Liên kết cao năng giữa hai nhóm phosphate ngoài cùng (liên kết phosphoanhydride)."],"ans":3,"exp":"ATP gồm adenine, đường ribose và 3 nhóm phosphate; hai liên kết ngoài cùng giữa các nhóm phosphate mang điện tích âm đẩy nhau nên có mức năng lượng cao, dễ thủy phân thành $ADP + P_i$."},{"id":"MCQ-CB-046","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hô hấp tế bào","q":"Trong hô hấp hiếu khí hoàn toàn 1 phân tử Glucose ở tế bào nhân thực, giai đoạn nào tạo ra lượng khí $CO_2$ nhiều nhất?","opts":["Chuỗi truyền electron hô hấp trên màng trong ti thể.","Giai đoạn Đường phân ở bào tương.","Chu trình Krebs (Acid citric) kết hợp bước oxy hóa Pyruvate.","Quá trình lên men Lactic."],"ans":2,"exp":"Đường phân không giải phóng $CO_2$. Oxy hóa 2 Pyruvate tạo $2\\text{ CO}_2$ và 2 vòng chu trình Krebs giải phóng $4\\text{ CO}_2$ (tổng 6 $CO_2$)."},{"id":"MCQ-CB-047","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hô hấp tế bào","q":"Chất nhận điện tử cuối cùng ở cuối chuỗi truyền electron hô hấp hiếu khí tại màng trong ti thể là phân tử nào?","opts":["Phân tử $CO_2$.","Phân tử $NAD^+$.","Phân tử Pyruvate.","Phân tử khí Oxygen ($O_2$), kết hợp với $H^+$ tạo thành nước ($H_2O$)."],"ans":3,"exp":"Oxygen có độ âm điện rất mạnh, nhận electron từ phức hợp IV (Cytochrome c oxidase) và kết hợp với proton $H^+$ tạo ra $H_2O$."},{"id":"MCQ-CB-048","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hô hấp tế bào","q":"Sản phẩm hữu cơ cuối cùng của quá trình lên men rượu (Ethanol) từ Glucose bởi nấm men <i>Saccharomyces cerevisiae</i> gồm những chất nào?","opts":["Ethanol ($C_2H_5OH$), khí $CO_2$ và lãi ròng $2\\text{ ATP}$.","Acid lactic ($C_3H_6O_3$) và $2\\text{ ATP}$, không có khí $CO_2$.","Acid acetic và khí $O_2$.","Acetyl-CoA, $6\\text{ CO}_2$ và $32\\text{ ATP}$."],"ans":0,"exp":"Lên men rượu khử Pyruvate qua trung gian Acetaldehyde để tạo Ethanol, giải phóng $CO_2$ (làm nở bánh mì) và thu lãi $2\\text{ ATP}$ từ đường phân."},{"id":"MCQ-CB-049","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quang hợp tế bào","q":"Khí Oxygen ($O_2$) giải phóng trong quá trình quang hợp ở thực vật có nguồn gốc trực tiếp từ phân tử nào?","opts":["Từ quá trình quang phân ly phân tử nước ($H_2O$) tại Quang hệ II (PSII).","Từ phân tử Diệp lục bị phân giải bởi tia UV.","Từ phân tử Glucose bị oxy hóa một phần.","Từ sự phân hủy phân tử $CO_2$ trong chu trình Calvin."],"ans":0,"exp":"Thí nghiệm sử dụng đồng vị nặng $^{18}\\text{O}$ chứng minh toàn bộ $O_2$ sinh ra trong quang hợp bắt nguồn từ sự quang phân ly $H_2O$, không phải từ $CO_2$."},{"id":"MCQ-CB-050","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quang hợp tế bào","q":"Các phân tử sắc tố Diệp lục (Chlorophyll a và b) ở màng Thylakoid hấp thụ mạnh nhất ánh sáng thuộc hai vùng phổ nào?","opts":["Chỉ hấp thụ tia tử ngoại và tia X.","Vùng ánh sáng xanh tím và vùng ánh sáng đỏ.","Chỉ hấp thụ tia hồng ngoại.","Vùng ánh sáng xanh lục và vùng vàng."],"ans":1,"exp":"Diệp lục hấp thụ mạnh tia xanh tím và đỏ để quang hợp, phản xạ hoặc truyền qua ánh sáng xanh lục nên lá cây có màu xanh lục."},{"id":"MCQ-CB-051","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Truyền tin tế bào","q":"Hormone steroid như Testosterone hay Estrogen có bản chất kỵ nước thường gắn với loại thụ thể nào của tế bào đích?","opts":["Thụ thể enzyme trên mặt ngoài màng tế bào.","Thụ thể nằm bên trong tế bào chất hoặc trong nhân tế bào.","Thành cellulose bên ngoài màng.","Kênh ion phụ thuộc phối tử trên màng sinh chất."],"ans":1,"exp":"Hormone steroid nhỏ và kỵ nước nên khuếch tán dễ dàng qua lớp kép phospholipid vào tế bào chất/nhân để gắn thụ thể nội bào và trực tiếp điều hòa phiên mã gen."},{"id":"MCQ-CB-052","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Truyền tin tế bào","q":"Trong hệ thống truyền tin tế bào động vật, các phân tử truyền tin trực tiếp giữa hai tế bào cạnh nhau thông qua khe nối (Gap junction) giống với cấu trúc nào ở thực vật?","opts":["Cầu sinh chất (Plasmodesmata).","Không bào trung tâm.","Đai Caspary.","Khí khổng."],"ans":0,"exp":"Cầu sinh chất ở thực vật và khe nối (gap junction) ở động vật đều là các kênh nối bào tương trực tiếp giúp ion và phân tử tín hiệu nhỏ đi qua nhanh chóng."},{"id":"MCQ-CB-053","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vi sinh vật","q":"Nhóm vi sinh vật nào sau đây sử dụng nguồn năng lượng từ phản ứng oxy hóa các chất vô cơ (như $NH_3, H_2S, Fe^{2+}$) và sử dụng nguồn carbon là $CO_2$?","opts":["Vi sinh vật quang tự dưỡng.","Vi sinh vật hóa tự dưỡng (Chemoautotrophs).","Vi sinh vật hóa dị dưỡng.","Vi sinh vật quang dị dưỡng."],"ans":1,"exp":"Vi khuẩn nitrat hóa, vi khuẩn oxy hóa lưu huỳnh hoặc sắt thuộc kiểu dinh dưỡng hóa tự dưỡng: nguồn năng lượng từ hóa chất vô cơ, nguồn carbon từ $CO_2$."},{"id":"MCQ-CB-054","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vi sinh vật","q":"Trong nuôi cấy không liên tục (hệ kín), ở pha nào tốc độ sinh trưởng riêng của quần thể vi khuẩn đạt giá trị cực đại và số lượng tế bào tăng theo cấp số nhân?","opts":["Pha suy vong (Death phase).","Pha cân bằng (Stationary phase).","Pha tiềm phát (Lag phase).","Pha lũy thừa (Log phase)."],"ans":3,"exp":"Ở pha lũy thừa, vi khuẩn đã thích nghi và tổng hợp đủ enzyme nên phân chia với thời gian thế hệ $g$ ngắn nhất và không đổi."},{"id":"MCQ-CB-055","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vi sinh vật","q":"Trong nuôi cấy vi khuẩn không liên tục, nguyên nhân chính làm quần thể chuyển từ pha lũy thừa sang pha cân bằng rồi pha suy vong là gì?","opts":["Nhiệt độ tủ ấm tự động hạ xuống $0^\\circ\\text{C}$.","Chất dinh dưỡng dần cạn kiệt và các chất độc hại từ trao đổi chất tích tụ tăng cao.","Vi khuẩn đột ngột mất toàn bộ plasmid.","Thời gian thế hệ giảm xuống bằng 0."],"ans":1,"exp":"Hệ kín không bổ sung dinh dưỡng mới và không rút bỏ chất thải nên dinh dưỡng cạn dần, pH thay đổi và chất độc tích tụ làm tốc độ chết tăng lên."},{"id":"MCQ-CB-056","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vi sinh vật","q":"Thời gian thế hệ ($g$) của một loài vi khuẩn là $20\\text{ phút}$. Từ 1 tế bào ban đầu nuôi trong điều kiện tối ưu, sau $2\\text{ giờ}$ thu được bao nhiêu tế bào?","opts":["$32$ tế bào.","$16$ tế bào.","$64$ tế bào.","$128$ tế bào."],"ans":2,"exp":"$2\\text{ giờ} = 120\\text{ phút} \\Rightarrow n = \\frac{120}{20} = 6$ lần phân chia. Số tế bào $= 1 \\times 2^6 = 64$."},{"id":"MCQ-CB-057","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vi sinh vật","q":"Ứng dụng quá trình lên men Lactic của vi khuẩn <i>Lactobacillus</i> được sử dụng trực tiếp trong sản xuất thực phẩm truyền thống nào sau đây?","opts":["Sản xuất cồn công nghiệp Ethanol và bia.","Muối dưa chua, làm sữa chua (yogurt) và ủ chua thức ăn chăn nuôi.","Sản xuất giấm ăn bằng oxy hóa hiếu khí.","Sản xuất nước mắm từ thủy phân đạm cá."],"ans":1,"exp":"Vi khuẩn lactic đồng hình hoặc dị hình chuyển đường (lactose, glucose) thành acid lactic làm giảm pH, tạo vị chua và ức chế vi khuẩn gây thối."},{"id":"MCQ-CB-058","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Virus","q":"Virus không được xem là một cơ thể sống hoàn chỉnh và chỉ có thể nhân lên bên trong tế bào vật chủ (ký sinh nội bào bắt buộc) vì lý do chính nào sau đây?","opts":["Virus chưa có cấu tạo tế bào, không có ribosome, không có hệ enzyme chuyển hóa và không tự tạo được ATP.","Vỏ capsid của virus không cho nước đi qua.","Kích thước của virus quá lớn không thể hấp thụ chất dinh dưỡng.","Virus không có bất kỳ loại vật chất di truyền (DNA hay RNA) nào."],"ans":0,"exp":"Virus chỉ gồm lõi nucleic acid và vỏ protein (capsid), có thể thêm vỏ ngoài lipid; nó phải mượn toàn bộ ribosome, ATP, amino acid và nucleotide của tế bào chủ."},{"id":"MCQ-CB-059","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Virus","q":"Chu trình nhân lên của thể thực khuẩn (Bacteriophage) mà trong đó hệ gen của phage gắn xen vào nhiễm sắc thể của vi khuẩn và nhân đôi cùng vi khuẩn qua nhiều thế hệ mà không phá vỡ tế bào ngay gọi là gì?","opts":["Chu trình sinh tan (Lytic cycle).","Chu trình tiềm tan (Lysogenic cycle).","Quá trình nội thực bào.","Quá trình tiếp hợp ở vi khuẩn."],"ans":1,"exp":"Trong chu trình tiềm tan, phage trở thành tiền phage (prophage) lồng ghép vào DNA vi khuẩn và chỉ chuyển sang chu trình sinh tan khi có tác nhân cảm ứng (tia UV, stress)."},{"id":"MCQ-CB-060","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Virus","q":"Thành phần cấu tạo nên lớp vỏ ngoài (Envelope) bao bọc bên ngoài capsid của nhiều loại virus động vật như HIV hay virus cúm có nguồn gốc chủ yếu từ đâu?","opts":["Từ lớp vỏ cellulose của tế bào thực vật.","Do vi khuẩn cộng sinh tổng hợp từ Peptidoglycan.","Do chính virus tự tổng hợp lipid trong môi trường tự do ngoài tế bào.","Từ màng sinh chất (hoặc màng nội bào) của tế bào vật chủ kèm theo gai glycoprotein do virus mã hóa."],"ans":3,"exp":"Khi nảy chồi thoát khỏi tế bào chủ, virus có vỏ ngoài mang theo một mảnh lớp kép phospholipid của màng tế bào chủ gắn các gai glycoprotein đặc hiệu."},{"id":"MCQ-CB-061","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Kỹ thuật tế bào","q":"Để tách riêng các bào quan khác nhau của tế bào dựa trên kích thước và khối lượng riêng (nhân lắng trước, tiếp đến ti thể, rồi vi thể và ribosome), nhà sinh học sử dụng kỹ thuật nào?","opts":["Nhuộm Gram bằng tím tinh thể.","Kỹ thuật PCR khuếch đại DNA.","Điện di trên gel polyacrylamide.","Ly tâm phân đoạn (Differential centrifugation) với tốc độ quay tăng dần."],"ans":3,"exp":"Nghiền đồng nhất mô rồi ly tâm ở các gia tốc tăng dần ($1000g \\rightarrow 20000g \\rightarrow 80000g \\rightarrow 150000g$) giúp phân tách lần lượt nhân, ti thể/lục lạp, mảnh màng và ribosome."},{"id":"MCQ-CB-062","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Khung xương tế bào","q":"Thành phần nào của bộ khung xương tế bào giúp định hình tế bào động vật, tham gia co cơ (trượt lên sợi myosin) và tạo vòng co thắt phân chia tế bào chất?","opts":["Sợi collagen ngoài chất nền ngoại bào.","Vi sợi (Microfilaments) cấu tạo từ protein Actin.","Vi ống (Microtubules) cấu tạo từ protein Tubulin.","Sợi trung gian cấu tạo từ protein Keratin."],"ans":1,"exp":"Vi sợi actin đường kính $7\\text{ nm}$ tương tác với myosin tạo chuyển động dòng tế bào chất, chân giả amip, co cơ và vòng thắt kỳ cuối nguyên phân."},{"id":"MCQ-CB-063","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Bào quan","q":"Ở các sinh vật đơn bào nước ngọt như Trùng đế giày (<i>Paramecium</i>), bào quan nào co bóp nhịp nhàng để bơm lượng nước dư thừa do thẩm thấu ra khỏi tế bào?","opts":["Nhân lớn.","Lysosome thứ cấp.","Lục lạp.","Không bào co bóp (Contractile vacuole)."],"ans":3,"exp":"Do sống trong nước ngọt nhược trương, nước liên tục thẩm thấu vào tế bào; không bào co bóp tiêu tốn ATP thu gom và đẩy nước ra ngoài chống vỡ tế bào."},{"id":"MCQ-CB-064","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc màng","q":"Trong mô hình khảm động của màng sinh chất (Singer - Nicolson, 1972), thành phần phân tử nào đóng vai trò làm thụ thể tiếp nhận tín hiệu hóa học, kênh vận chuyển và dấu chuẩn nhận diện tế bào?","opts":["Các đuôi acid béo no của phospholipid.","Protein màng (xuyên màng, bám màng) và Glycoprotein.","Các hạt tinh bột bám mặt ngoài.","Cholesterol nằm sâu trong lõi kỵ nước."],"ans":1,"exp":"Protein màng thực hiện đa số chức năng đặc hiệu của màng: vận chuyển, enzyme, thụ thể, neo khung xương và nhận diện tế bào (glycoprotein/glycolipid)."},{"id":"MCQ-CB-065","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Chất nền ngoại bào","q":"Các tế bào biểu mô lót thành ruột liên kết cực kỳ khít chặt với nhau ngăn không cho dịch tiêu hóa rò rỉ qua khe giữa các tế bào nhờ loại cầu nối nào?","opts":["Thể liên kết (Desmosome).","Cầu sinh chất (Plasmodesmata).","Liên kết khe (Gap junction).","Liên kết bịt / Mối nối chặt (Tight junction)."],"ans":3,"exp":"Mối nối chặt (Tight junction) ép sát màng hai tế bào liền kề nhau tạo hàng rào không thấm nước giữa khoang ruột và mô bên dưới."},{"id":"MCQ-CB-066","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Lục lạp & Ti thể","q":"Bằng chứng nào sau đây ủng hộ mạnh mẽ nhất cho Thuyết nội cộng sinh (Endosymbiotic theory) về nguồn gốc tiến hóa của Ti thể và Lục lạp?","opts":["Cả hai đều chỉ tổng hợp ATP khi có ánh sáng mặt trời.","Cả hai đều có mặt trong mọi tế bào vi khuẩn hiếu khí hiện đại.","Cả hai đều có màng kép, chứa DNA vòng trần riêng, ribosome 70S và tự nhân đôi độc lập bằng phân đôi giống vi khuẩn.","Cả hai đều không chứa protein và lipid trên màng."],"ans":2,"exp":"Ti thể (từ vi khuẩn hiếu khí cổ đại) và lục lạp (từ vi khuẩn lam cổ đại) giữ lại DNA vòng không gắn histone, ribosome 70S và cơ chế nhân đôi kiểu phân đôi."},{"id":"MCQ-CB-067","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hô hấp tế bào","q":"Trong quá trình hô hấp hiếu khí, khi Pyruvate ($3\\text{ C}$) đi từ bào tương vào chất nền ti thể để chuẩn bị bước vào chu trình Krebs, nó được chuyển hóa thành hợp chất nào?","opts":["Acetyl-CoA ($2\\text{ C}$), đồng thời giải phóng $1\\text{ CO}_2$ và tạo $1\\text{ NADH}$ cho mỗi Pyruvate.","Lactate ($3\\text{ C}$) và $1\\text{ FADH}_2$.","Oxaloacetate ($4\\text{ C}$) và $2\\text{ ATP}$.","Ethanol ($2\\text{ C}$) và $1\\text{ NADPH}$."],"ans":0,"exp":"Phức hợp Pyruvate dehydrogenase xúc tác khử carboxyl oxy hóa Pyruvate ($3C$) thành Acetyl-CoA ($2C$), sinh ra $1\\text{ CO}_2$ và $1\\text{ NADH}$."},{"id":"MCQ-CB-068","topic":"cellbio","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Vi sinh vật","q":"Khi thực hiện nhuộm Gram vi khuẩn, vi khuẩn Gram dương ($\\text{Gram}^+$) bắt màu tím, còn vi khuẩn Gram âm ($\\text{Gram}^-$) bắt màu hồng đỏ là do sự khác biệt nào?","opts":["Vi khuẩn $\\text{Gram}^+$ không có thành tế bào còn $\\text{Gram}^-$ có thành cellulose.","Vi khuẩn $\\text{Gram}^+$ có lớp thành Peptidoglycan rất dày giữ chặt phức hợp tím tinh thể - iod; $\\text{Gram}^-$ có lớp Peptidoglycan mỏng và màng ngoài chứa lipopolysaccharide (LPS).","Vi khuẩn $\\text{Gram}^-$ có nhân hoàn chỉnh có màng nhân bao bọc.","Vi khuẩn $\\text{Gram}^+$ có ti thể còn $\\text{Gram}^-$ không có ti thể."],"ans":1,"exp":"Thành Peptidoglycan dày của vi khuẩn $\\text{Gram}^+$ mất nước và thu nhỏ lỗ khi rửa cồn nên giữ màu tím; thành mỏng của $\\text{Gram}^-$ bị rửa trôi màu tím và bắt màu thuốc nhuộm đối safranin."},{"id":"MCQ-CB-069","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Động học Enzyme","q":"Một phản ứng enzyme tuân theo động học Michaelis-Menten có $V_{\\max} = 120\\text{ }\\mu\\text{mol/phút}$ và $K_m = 4\\text{ mM}$. Tại nồng độ cơ chất $[S] = 12\\text{ mM}$, tốc độ phản ứng ban đầu $v$ bằng bao nhiêu?","opts":["$90\\text{ }\\mu\\text{mol/phút}$.","$80\\text{ }\\mu\\text{mol/phút}$.","$100\\text{ }\\mu\\text{mol/phút}$.","$60\\text{ }\\mu\\text{mol/phút}$."],"ans":0,"exp":"Áp dụng $v = \\frac{V_{\\max} \\cdot [S]}{K_m + [S]} = \\frac{120 \\times 12}{4 + 12} = \\frac{1440}{16} = 90\\text{ }\\mu\\text{mol/phút}$."},{"id":"MCQ-CB-070","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Động học Enzyme","q":"Trên đồ thị Lineweaver-Burk (biểu diễn $\\frac{1}{v}$ theo $\\frac{1}{[S]}$), nếu thêm một chất ức chế X làm hai đường thẳng (có X và không có X) cắt nhau tại đúng một điểm trên trục tung ($\\frac{1}{V_{\\max}}$ không đổi), chất X là:","opts":["Chất ức chế không cạnh tranh thuần túy.","Chất gây biến tính không thuận nghịch toàn bộ enzyme.","Chất ức chế phi cạnh tranh (uncompetitive) gắn vào phức hợp ES.","Chất ức chế cạnh tranh (cạnh tranh trực tiếp tại trung tâm hoạt động)."],"ans":3,"exp":"Khi $V_{\\max}$ giữ nguyên (cùng giao điểm trục tung $1/V_{\\max}$) và độ dốc $K_m/V_{\\max}$ tăng (tăng $K_m$ biểu kiến), đó là đặc trưng của chất ức chế cạnh tranh."},{"id":"MCQ-CB-071","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Động học Enzyme","q":"Kháng sinh Sulfonamide (thuốc nhóm Sulfa) có cấu trúc tương tự phân tử PABA (para-aminobenzoic acid) là cơ chất của enzyme tổng hợp acid folic ở vi khuẩn. Cơ chế diệt khuẩn của thuốc Sulfa là gì?","opts":["Chọc thủng màng sinh chất vi khuẩn như chất tẩy rửa.","Ức chế cạnh tranh enzyme tổng hợp acid folic của vi khuẩn, ngăn vi khuẩn tổng hợp nucleotide tạo DNA.","Ức chế không cạnh tranh bằng cách phá hủy ribosome 70S.","Ức chế enzyme RNA polymerase của người."],"ans":1,"exp":"Sulfonamide bắt chước cấu trúc PABA và chiếm giữ trung tâm hoạt động của enzyme dihydropteroate synthase ở vi khuẩn; người không tự tổng hợp acid folic từ PABA nên không bị ảnh hưởng."},{"id":"MCQ-CB-072","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Động học Enzyme","q":"Trong con đường chuyển hóa gồm 5 bước $A \\xrightarrow{E_1} B \\xrightarrow{E_2} C \\xrightarrow{E_3} D \\xrightarrow{E_4} P$, sản phẩm cuối $P$ dư thừa gắn vào vị trí dị lập thể của enzyme $E_1$ làm $E_1$ mất hoạt tính. Cơ chế điều hòa này mang lại lợi ích sinh học gì?","opts":["Ức chế ngược (Feedback inhibition), giúp tế bào ngừng tiêu tốn nguyên liệu và ATP để tạo các chất trung gian $B, C, D$ không cần thiết.","Hoạt hóa dị lập thể để tăng cường tích lũy chất trung gian $B$.","Biến đổi $P$ ngược trở lại thành $A$ nhờ $E_1$.","Phá hủy vĩnh viễn gen mã hóa enzyme $E_1$."],"ans":0,"exp":"Ức chế ngược lên enzyme đầu tiên của chuỗi chuyển hóa ($E_1$) ngăn chặn lãng phí cơ chất và năng lượng khi sản phẩm cuối đã dư thừa."},{"id":"MCQ-CB-073","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Động học Enzyme","q":"Đồ thị tốc độ phản ứng theo nồng độ cơ chất $[S]$ của một enzyme dị lập thể nhiều tiểu phần (như Hemoglobin hoặc PFK-1) thường có dạng hình chữ S (Sigmoidal) thay vì đường cong Hyperbol. Nguyên nhân là gì?","opts":["Hiện tượng gắn hợp tác (Cooperativity): khi một cơ chất gắn vào một tiểu phần làm tăng ái lực gắn cơ chất ở các tiểu phần còn lại.","Do cơ chất bị biến tính ở nồng độ cao.","Do sản phẩm phản ứng luôn luôn kích thích enzyme.","Do enzyme chỉ có duy nhất một trung tâm hoạt động."],"ans":0,"exp":"Sự chuyển trạng thái cấu hình từ dạng T (ái lực thấp) sang dạng R (ái lực cao) đồng loạt giữa các tiểu phần tạo đường cong chữ S nhạy cảm với thay đổi nồng độ $[S]$."},{"id":"MCQ-CB-074","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Màng sinh chất","q":"Nếu thay thế phần lớn các acid béo no trong màng sinh chất của một tế bào nuôi cấy bằng các acid béo không no có nối đôi dạng <i>cis</i>, điều gì sẽ xảy ra với cấu trúc màng ở nhiệt độ $20^\\circ\\text{C}$?","opts":["Màng trở nên đông cứng và mất hoàn toàn khả năng vận chuyển chất.","Tính lỏng (độ linh hoạt) của màng tăng lên vì các đuôi có nối đôi <i>cis</i> bị gấp khúc, không thể xếp khít vào nhau.","Màng hoàn toàn không cho khí $O_2$ đi qua.","Lớp kép phospholipid tách rời thành hai lớp đơn độc lập."],"ans":1,"exp":"Liên kết đôi <i>cis</i> tạo góc gập ở đuôi hydrocarbon làm giảm tương tác Van der Waals giữa các phân tử phospholipid, duy trì tính lỏng ở nhiệt độ thấp."},{"id":"MCQ-CB-075","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thẩm thấu & Thế nước","q":"Một túi thẩm thấu làm bằng màng bán thấm (chỉ cho nước đi qua, không cho đường đi qua) chứa dung dịch Sucrose $0.4\\text{ M}$ được nhúng vào cốc nước chứa dung dịch Sucrose $0.1\\text{ M}$. So với ban đầu, khối lượng túi sau 1 giờ sẽ như thế nào?","opts":["Giảm đi vì nước thoát từ túi ra cốc.","Không thay đổi vì áp suất thẩm thấu hai bên bằng nhau.","Giảm đi vì đường Sucrose khuếch tán từ trong túi ra ngoài cốc.","Tăng lên vì nước di chuyển từ dung dịch $0.1\\text{ M}$ (nhược trương) vào trong túi $0.4\\text{ M}$ (ưu trương)."],"ans":3,"exp":"Màng không cho Sucrose qua nên chỉ nước thẩm thấu từ nơi có nồng độ chất tan thấp ($0.1\\text{ M}$, thế nước cao hơn) sang nơi nồng độ chất tan cao ($0.4\\text{ M}$)."},{"id":"MCQ-CB-076","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thẩm thấu & Thế nước","q":"Cơ chế bảo quản thực phẩm bằng cách ướp muối mặn (làm cá khô, dưa muối) hoặc ngâm đường đặc (làm mứt quả) ngăn chặn được vi khuẩn gây thối hỏng dựa trên nguyên lý nào?","opts":["Đường Sucrose ngăn không cho oxy tiếp xúc với thức ăn.","Môi trường muối hoặc đường rất ưu trương kéo nước ra khỏi tế bào vi khuẩn gây co nguyên sinh mạnh khiến vi khuẩn chết hoặc ngừng sinh trưởng.","Muối làm tăng độ pH lên trên 12 gây biến tính màng vi khuẩn.","Muối ăn và đường đóng vai trò kháng sinh đặc hiệu phá vỡ DNA vi khuẩn."],"ans":1,"exp":"Nước bị rút ra khỏi tế bào vi sinh vật làm giảm hoạt độ nước nội bào, ức chế enzyme trao đổi chất của vi khuẩn và nấm mốc."},{"id":"MCQ-CB-077","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Vận chuyển qua màng","q":"Bệnh xơ nang (Cystic fibrosis) là bệnh di truyền lặn gây tích tụ dịch nhầy đặc quánh ở phổi và tụy. Nguyên nhân ở cấp độ màng tế bào là do khiếm khuyết loại protein màng nào?","opts":["Kênh ion Chloride ($Cl^-$) CFTR nằm trên màng sinh chất tế bào biểu mô.","Thụ thể tiếp nhận LDL-cholesterol.","Kênh vận chuyển nước Aquaporin-2 ở thận.","Bơm proton $H^+$-ATPase trong Lysosome."],"ans":0,"exp":"Đột biến gen CFTR làm hỏng kênh vận chuyển ion $Cl^-$ ra khỏi tế bào biểu mô đường hô hấp, khiến nước không theo ra để làm loãng lớp chất nhầy."},{"id":"MCQ-CB-078","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Vận chuyển qua màng","q":"Trong bệnh tăng cholesterol máu gia đình (Familial hypercholesterolemia), nồng độ LDL-cholesterol trong máu bệnh nhân tăng rất cao gây xơ vữa động mạch sớm. Cơ chế nhập bào nào bị khiếm khuyết ở tế bào gan?","opts":["Xuất bào qua túi tiết từ bộ máy Golgi.","Khuếch tán thụ động cholesterol tự do qua màng.","Nhập bào qua trung gian thụ thể (Receptor-mediated endocytosis) do thiếu hoặc hỏng thụ thể LDL trên màng tế bào.","Thực bào nhờ đại thực bào phế nang."],"ans":2,"exp":"Các hạt LDL trong máu được thu nhận vào tế bào nhờ gắn đặc hiệu vào thụ thể LDL ở vùng hố phủ clathrin; khi thiếu thụ thể LDL, cholesterol tích tụ trong máu."},{"id":"MCQ-CB-079","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hô hấp tế bào","q":"Tính toán tổng hợp từ 1 phân tử Glucose qua đường phân, oxy hóa pyruvate và chu trình Krebs (chưa tính chuỗi truyền electron): số phân tử $\\text{ATP}$ tạo trực tiếp ở mức cơ chất, $\\text{NADH}$ và $\\text{FADH}_2$ thu được lần lượt là:","opts":["$4\\text{ ATP}$, $8\\text{ NADH}$ và $4\\text{ FADH}_2$.","$4\\text{ ATP}$ (lãi ròng ở mức cơ chất), $10\\text{ NADH}$ và $2\\text{ FADH}_2$.","$2\\text{ ATP}$, $6\\text{ NADH}$ và $2\\text{ FADH}_2$.","$32\\text{ ATP}$, $10\\text{ NADH}$ và $2\\text{ FADH}_2$."],"ans":1,"exp":"Đường phân: $+2\\text{ ATP}, +2\\text{ NADH}$; Oxy hóa 2 Pyruvate: $+2\\text{ NADH}$; 2 vòng Krebs: $+2\\text{ GTP(ATP)}, +6\\text{ NADH}, +2\\text{ FADH}_2$. Tổng: $4\\text{ ATP}, 10\\text{ NADH}, 2\\text{ FADH}_2$."},{"id":"MCQ-CB-080","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hô hấp tế bào","q":"Trong tế bào nấm men chuyển từ môi trường yếm khí sang môi trường sục khí $O_2$ dồi dào, tốc độ tiêu thụ Glucose giảm hẳn xuống nhưng tốc độ tổng hợp ATP vẫn tăng (Hiệu ứng Pasteur). Giải thích nào đúng nhất?","opts":["Nấm men chuyển sang quang hợp sử dụng $CO_2$ thay cho Glucose.","Khi có $O_2$, enzyme đường phân bị oxy hóa phá hủy hoàn toàn.","Khi có $O_2$, hô hấp hiếu khí tạo khoảng $30-32\\text{ ATP}$/Glucose (gấp ~15 lần lên men), làm tỉ lệ $\\text{ATP/AMP}$ tăng cao và ức chế dị lập thể enzyme PFK-1 của đường phân.","Chu trình Krebs ngừng hoạt động khi có $O_2$."],"ans":2,"exp":"Hiệu suất ATP cao khi có $O_2$ làm tăng nồng độ ATP và Citrate, từ đó ức chế ngược dị lập thể enzyme PFK-1, giảm tốc độ tiêu thụ Glucose."},{"id":"MCQ-CB-081","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hô hấp tế bào","q":"Tại sao quá trình oxy hóa $1\\text{ NADH}$ qua chuỗi truyền electron ti thể tạo được nhiều ATP hơn (khoảng $2.5\\text{ ATP}$) so với oxy hóa $1\\text{ FADH}_2$ (khoảng $1.5\\text{ ATP}$)?","opts":["Vì phân tử $FADH_2$ nằm ở ngoài bào tương không vào được ti thể.","Vì phức hợp II làm tiêu hủy bớt ATP.","Vì $NADH$ nhường electron ở Phức hợp I (bơm được $H^+$ qua 3 phức hợp I, III, IV), còn $FADH_2$ nhường electron ở Phức hợp II (không bơm $H^+$, chỉ qua III và IV).","Vì $NADH$ chứa nhiều nhóm phosphate cao năng hơn $FADH_2$."],"ans":2,"exp":"Electron từ $NADH$ thúc đẩy bơm tổng cộng $10\\text{ }H^+$ qua màng trong ti thể (tại I, III, IV), còn từ $FADH_2$ chỉ bơm $6\\text{ }H^+$ (tại III, IV) nên tạo ít ATP hơn."},{"id":"MCQ-CB-082","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hô hấp tế bào","q":"Tế bào ung thư thường tăng cường tốc độ đường phân và tiết ra nhiều Lactate ngay cả khi có đầy đủ oxy (Hiệu ứng Warburg). Ý nghĩa sinh học giúp tế bào ung thư tăng sinh nhanh của hiệu ứng này là gì?","opts":["Tế bào ung thư không thể hấp thụ $O_2$ qua màng sinh chất.","Đường phân tạo ra nhiều ATP trên mỗi phân tử Glucose hơn chuỗi truyền electron.","Acid lactic tiêu diệt trực tiếp hệ gen của tế bào ung thư.","Các chất trung gian của đường phân (và con đường pentose phosphate nhánh) cung cấp nguyên liệu carbon tổng hợp nhanh nucleotide, lipid và amino acid cho phân bào liên tục."],"ans":3,"exp":"Dù lãi ít ATP trên mỗi Glucose, đường phân tốc độ cực nhanh cung cấp dồi dào khung carbon (ribose-5-P, NADPH, G3P, serine) để nhân đôi sinh khối phân bào nhanh."},{"id":"MCQ-CB-083","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quang hợp tế bào","q":"Trong pha sáng quang hợp bình thường (dòng electron không vòng), electron bị mất đi ở tâm phản ứng $P_{680}$ của Quang hệ II (PSII) và $P_{700}$ của Quang hệ I (PSI) được bù lại trực tiếp từ đâu?","opts":["Cả $P_{680}^+$ và $P_{700}^+$ đều nhận electron trực tiếp từ $NADPH$.","$P_{680}^+$ nhận electron từ quang phân ly $H_2O$; còn $P_{700}^+$ nhận electron từ chuỗi truyền $e^-$ đến từ PSII (qua Plastocyanin).","$P_{680}^+$ nhận electron từ $CO_2$; $P_{700}^+$ nhận electron từ $H_2O$.","Cả hai nhận electron từ chất nền ti thể."],"ans":1,"exp":"Sơ đồ chữ Z: $H_2O \\rightarrow PSII (P_{680}) \\rightarrow PQ \\rightarrow \\text{Cytochrome } b_6f \\rightarrow PC \\rightarrow PSI (P_{700}) \\rightarrow Fd \\rightarrow NADP^+$."},{"id":"MCQ-CB-084","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quang hợp tế bào","q":"Thuốc diệt cỏ DCMU (Diuron) phong bế vị trí gắn Plastoquinone ($Q_B$) trên Quang hệ II, ngăn cản dòng electron từ PSII sang phức hợp Cytochrome $b_6f$. Hậu quả nào xảy ra khi chiếu sáng lục lạp có xử lý DCMU?","opts":["Ngừng quang phân ly nước tạo $O_2$, ngừng tạo $NADPH$ và không cố định được $CO_2$ (nhưng nếu cấp nhân tạo chất cho $e^-$ cho PSI vẫn có thể chạy dòng vòng tạo ATP).","Chỉ ức chế chu trình Krebs ở ti thể.","Quang phân ly nước giải phóng $O_2$ tăng gấp đôi.","Tốc độ chu trình Calvin tăng vọt nhờ tích lũy $NADPH$."],"ans":0,"exp":"DCMU khóa dòng $e^-$ ra khỏi PSII nên PSII không thể hoàn nguyên để tiếp tục tách nước tạo $O_2$, đồng thời cắt nguồn electron tới $NADP^+$."},{"id":"MCQ-CB-085","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quang hợp tế bào","q":"Tại sao dòng vận chuyển electron vòng (Cyclic electron flow) chỉ sử dụng Quang hệ I (PSI) lại cần thiết ở lục lạp ngay cả khi dòng không vòng đang hoạt động?","opts":["Vì dòng vòng giúp giải phóng $CO_2$ từ Stroma.","Vì dòng vòng tạo ra thêm nhiều phân tử $O_2$ và $NADPH$.","Vì chu trình Calvin tiêu thụ tỉ lệ $3\\text{ ATP} : 2\\text{ NADPH}$, trong khi dòng không vòng tạo ít ATP hơn tỉ lệ này; dòng vòng tạo thêm ATP mà không tạo thêm $NADPH$.","Vì dòng vòng thay thế hoàn toàn enzyme RuBisCO."],"ans":2,"exp":"Mỗi lượt chu trình Calvin cố định $3\\text{ CO}_2$ cần $9\\text{ ATP}$ và $6\\text{ NADPH}$ (tỉ lệ $1.5:1$). Dòng vòng chuyển $e^-$ từ Ferredoxin quay lại Cytochrome $b_6f$ để bơm thêm $H^+$ tạo ATP cân bằng tỉ lệ."},{"id":"MCQ-CB-086","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Truyền tin tế bào","q":"Thụ thể Tyrosine kinase (RTK) thường tham gia đáp ứng với các yếu tố tăng trưởng (như EGF, PDGF) và Insulin. Bước kích hoạt đầu tiên ngay khi hai phân tử phối tử (ligand) gắn vào hai đơn phân RTK trên màng là gì?","opts":["Hai đơn phân thụ thể bắt cặp (dimer hóa) và tự phosphoryl hóa chéo lẫn nhau vào các gốc Tyrosine ở vùng đuôi nội bào.","Thụ thể trực tiếp thủy phân $cAMP$ thành $AMP$.","Thụ thể tách khỏi màng đi thẳng vào nhân để cắt DNA.","Thụ thể mở kênh cho $Na^+$ ồ ạt đi ra ngoài."],"ans":0,"exp":"Gắn ligand gây dimer hóa RTK, kích hoạt miền kinase nội bào tự gắn nhóm phosphate từ ATP lên các gốc Tyrosine, tạo điểm neo cho các protein truyền tin tiếp theo."},{"id":"MCQ-CB-087","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Truyền tin tế bào","q":"Một loại thuốc ức chế đặc hiệu enzyme Phosphodiesterase (enzyme phân giải cAMP thành 5'-AMP) — tương tự cơ chế của Caffeine hoặc Sildenafil — sẽ gây ra tác động nào trong con đường truyền tin qua cAMP?","opts":["Bất hoạt Protein kinase A (PKA) ngay lập tức.","Ngăn cản hoàn toàn sự tổng hợp cAMP từ ATP.","Kéo dài và khuếch đại đáp ứng của tế bào với tín hiệu ban đầu do nồng độ cAMP nội bào được duy trì ở mức cao lâu hơn.","Đẩy thụ thể GPCR ra khỏi màng tế bào."],"ans":2,"exp":"Phosphodiesterase bình thường giúp tắt tín hiệu cAMP nhanh chóng. Khi ức chế enzyme này, cAMP không bị phân hủy nên tiếp tục hoạt hóa PKA kéo dài."},{"id":"MCQ-CB-088","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Truyền tin tế bào","q":"Trong con đường truyền tin qua $IP_3$ và $Ca^{2+}$, khi enzyme Phospholipase C (PLC) cắt phospholipid $PIP_2$ trên màng sinh chất thành $DAG$ và $IP_3$, phân tử $IP_3$ khuếch tán vào bào tương để thực hiện nhiệm vụ gì?","opts":["Gắn vào kênh $Ca^{2+}$ phối tử trên màng lưới nội chất (ER), mở kênh giải phóng ồ ạt $Ca^{2+}$ từ lòng ER ra bào tương.","Gắn vào màng ti thể kích thích tổng hợp Glucose.","Ức chế hoạt động của bơm $Na^+/K^+$.","Hoạt hóa trực tiếp RNA polymerase trong nhân."],"ans":0,"exp":"Inositol trisphosphate ($IP_3$) tan trong nước, di chuyển đến màng ER để mở kênh giải phóng dự trữ $Ca^{2+}$ vào bào tương làm chất truyền tin thứ hai."},{"id":"MCQ-CB-089","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Apoptosis","q":"Điểm khác biệt quan trọng nhất giữa sự chết tế bào theo chương trình (Apoptosis) và sự chết tế bào do tổn thương hoại tử (Necrosis) đối với mô xung quanh là gì?","opts":["Necrosis luôn có lợi giúp tạo ngón tay ở phôi người.","Apoptosis chỉ xảy ra ở vi khuẩn còn Necrosis chỉ xảy ra ở thực vật.","Trong Apoptosis, tế bào co lại, DNA cắt đoạn gọn và đóng gói thành các thể apoptotic để đại thực bào dọn dẹp mà KHÔNG gây phản ứng viêm; còn Necrosis làm tế bào trương vỡ tung gây viêm mô.","Apoptosis không tiêu tốn ATP còn Necrosis tiêu tốn rất nhiều ATP."],"ans":2,"exp":"Apoptosis giữ nguyên vẹn màng bao các mảnh vỡ tế bào (thể apoptotic) để dọn sạch sẽ êm thấm, không giải phóng dịch bào tương gây viêm như hoại tử."},{"id":"MCQ-CB-090","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Apoptosis","q":"Sự hình thành bàn tay có 5 ngón tách rời ở phôi người (từ bản tay có màng nối giữa các ngón ở tuần phôi thứ 6) là kết quả trực tiếp của quá trình sinh học nào?","opts":["Sự co nguyên sinh của tế bào biểu bì do mất nước.","Chết tế bào theo chương trình (Apoptosis) có chọn lọc ở các tế bào mô kẽ giữa các ngón.","Quá trình hoại tử do thiếu máu cục bộ ngẫu nhiên.","Sự biệt hóa ngược tế bào cơ thành tế bào sụn."],"ans":1,"exp":"Apoptosis đóng vai trò điêu khắc hình thái trong phát triển phôi (tách ngón tay/chân, tiêu biến ống trung thận, loại bỏ tế bào thần kinh thừa)."},{"id":"MCQ-CB-091","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Màng & Bào quan","q":"Các tế bào tuyến tụy ngoại tiết tổng hợp lượng lớn enzyme tiêu hóa (trypsinogen, amylase) để tiết vào tá tràng. Nếu xử lý các tế bào này bằng thuốc Cytochalasin B (phá hủy vi sợi actin) hoặc Nocodazole (phá hủy vi ống), quá trình nào bị đình trệ trực tiếp?","opts":["Sự sao chép DNA trong nhân ở pha S.","Sự thẩm thấu nước qua kênh Aquaporin.","Sự vận chuyển các túi tiết từ lưới nội chất đến Golgi và từ Golgi ra màng sinh chất để xuất bào.","Quá trình đường phân trong bào tương."],"ans":2,"exp":"Các túi vận chuyển nội bào di chuyển dọc theo 'đường ray' vi ống (nhờ protein động cơ Kinesin/Dynein) và mạng lưới vi sợi actin vỏ tế bào để đến vị trí xuất bào."},{"id":"MCQ-CB-092","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Màng & Bào quan","q":"Để xác định xem một protein xuyên màng có phần đầu N quay vào bào tương hay quay ra ngoài màng hay không khi nghiên cứu cấu trúc túi màng ER cô lập (microsome), người ta xử lý túi nguyên vẹn bằng enzyme Protease (không thấm qua màng) rồi chạy điện di. Kết quả nào cho thấy protein X có một miền lồi ra mặt ngoài túi microsome?","opts":["Protein X bị phân hủy hoàn toàn thành amino acid tự do khi không có chất tẩy rửa.","Khối lượng phân tử protein X hoàn toàn không đổi khi có hay không có chất tẩy rửa.","Protein X tăng gấp đôi khối lượng.","Sau khi xử lý Protease ở ngoài túi nguyên vẹn (không có chất tẩy rửa), khối lượng phân tử của protein X bị giảm đi một đoạn (cắt mất phần nhô ra ngoài)."],"ans":3,"exp":"Protease không đi qua lớp kép lipid nên chỉ cắt được phần polypeptide thò ra phía ngoài của túi màng; phần xuyên màng và phần trong lòng túi được lớp kép bảo vệ."},{"id":"MCQ-CB-093","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Màng & Bào quan","q":"Chức năng đánh dấu 'địa chỉ' gắn gốc Mannose-6-phosphate (M6P) tại mặt <i>cis</i>/mạng lưới <i>trans</i>-Golgi giúp định hướng các enzyme mới tổng hợp đi tới đúng bào quan đích nào?","opts":["Ti thể.","Peroxisome.","Nhân tế bào.","Lysosome."],"ans":3,"exp":"Các hydrolase acid của Lysosome được gắn nhãn Mannose-6-phosphate trong bộ máy Golgi để thụ thể M6P trên màng Golgi đóng gói vào túi vận chuyển tới thể nội bào muộn / Lysosome."},{"id":"MCQ-CB-094","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hóa sinh Protein","q":"Các phân tử protein mới dịch mã muốn gấp cuộn đúng cấu hình không gian ba chiều mà không bị kết tụ sai trong môi trường bào tương đông đúc cần sự hỗ trợ của nhóm protein nào?","opts":["Protein Chaperonin (như phức hợp Hsp60/GroEL).","Histone H1.","Kênh ion phụ thuộc điện thế.","Enzyme DNA helicase."],"ans":0,"exp":"Chaperone và Chaperonin (như Hsp70, GroEL/GroES) tạo khoang cách ly kỵ nước giúp chuỗi polypeptide gấp cuộn đúng cấu trúc tự nhiên."},{"id":"MCQ-CB-095","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hóa sinh Protein","q":"Bệnh bò điên (BSE) và bệnh thoái hóa thần kinh CJD ở người do tác nhân Prion gây ra. Bản chất sinh học của Prion là gì?","opts":["Một đoạn phân tử RNA vòng trần (Viroid) chỉ gồm 300 nucleotide.","Một vi khuẩn nội ký sinh cực nhỏ không có thành tế bào.","Một virus có lõi RNA sợi đơn không có vỏ capsid.","Một loại protein bình thường của tế bào thần kinh ($PrP^C$) bị gấp cuộn sai cấu hình không gian (giàu phiến $\\beta$ tạo $PrP^{Sc}$), có khả năng ép các protein lành cùng loại gấp cuộn sai theo kiểu dây chuyền."],"ans":3,"exp":"Prion hoàn toàn không chứa nucleic acid (DNA hay RNA); nó truyền bệnh bằng cơ chế cảm ứng biến đổi cấu hình bậc 2-3 từ xoắn $\\alpha$ sang phiến $\\beta$ không tan."},{"id":"MCQ-CB-096","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Vi sinh vật","q":"Trong kỹ thuật lên men sản xuất kháng sinh Penicillin từ nấm mốc <i>Penicillium chrysogenum</i>, tại sao người ta thường thu hoạch sản phẩm kháng sinh nhiều nhất ở giai đoạn cuối pha lũy thừa và pha cân bằng?","opts":["Vì Penicillin là chất chuyển hóa thứ cấp (secondary metabolite) không cần thiết cho tăng trưởng sơ cấp mà được tổng hợp mạnh khi tốc độ sinh trưởng chậm lại dưới áp lực cạnh tranh.","Vì nấm mốc chỉ bắt đầu hô hấp khi hết pha cân bằng.","Vì Penicillin bị phá hủy ngay lập tức nếu sinh trưởng ở pha log.","Vì ở pha tiềm phát nấm mốc chưa có DNA."],"ans":0,"exp":"Kháng sinh và nhiều sắc tố là sản phẩm trao đổi chất thứ cấp (idiophase) được tạo ra chủ yếu ở pha cân bằng, khác với sản phẩm sơ cấp như ethanol hay acid amin."},{"id":"MCQ-CB-097","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Vi sinh vật","q":"Một quần thể vi khuẩn ban đầu có $N_0 = 10^3$ tế bào/ml được nuôi cấy. Sau $3\\text{ giờ}$ ở pha lũy thừa, mật độ đạt $6.4 \\times 10^4$ tế bào/ml. Thời gian thế hệ ($g$) của loài vi khuẩn này là bao nhiêu phút?","opts":["$20\\text{ phút}$.","$15\\text{ phút}$.","$45\\text{ phút}$.","$30\\text{ phút}$."],"ans":3,"exp":"$\\frac{N_t}{N_0} = \\frac{64000}{1000} = 64 = 2^6 \\Rightarrow n = 6$ thế hệ trong $180\\text{ phút} \\Rightarrow g = \\frac{180}{6} = 30\\text{ phút}$."},{"id":"MCQ-CB-098","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Vi sinh vật","q":"Tại sao thuốc kháng sinh Penicillin diệt được vi khuẩn đang sinh trưởng mạnh rất hiệu quả, nhưng lại KHÔNG có tác dụng đối với Mycoplasma và virus?","opts":["Vì Penicillin ức chế tổng hợp cầu nối Peptidoglycan ở thành tế bào; trong khi Mycoplasma (không có thành tế bào) và Virus (không phải tế bào, không có thành Peptidoglycan) không có đích tác động này.","Vì virus tự tiết ra enzyme phân hủy Penicillin.","Vì Mycoplasma có lớp vỏ Peptidoglycan dày gấp 100 lần vi khuẩn thường.","Vì Penicillin chỉ ức chế ribosome 80S."],"ans":0,"exp":"Penicillin ức chế enzyme transpeptidase nối chéo Peptidoglycan. Bất kỳ tác nhân nào thiếu thành Peptidoglycan (như Mycoplasma, Archaea, Virus, tế bào người) đều kháng tự nhiên Penicillin."},{"id":"MCQ-CB-099","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Vi sinh vật","q":"Khi kiểm tra một chủng vi khuẩn đột biến thấy nó mất khả năng sống trên môi trường tối thiểu (chỉ có đường glucose và muối khoáng), nhưng lại mọc bình thường nếu bổ sung thêm amino acid Histidine. Chủng vi khuẩn này được gọi là gì?","opts":["Chủng nguyên dưỡng Histidine ($His^+$).","Chủng hóa tự dưỡng bắt buộc.","Chủng kháng kháng sinh.","Chủng khuyết dưỡng Histidine ($His^-$)."],"ans":3,"exp":"Vi sinh vật khuyết dưỡng (Auxotroph) bị mất chức năng một gen trong con đường tổng hợp chất thiết yếu (như $His^-$), phải bổ sung chất đó vào môi trường mới sống được."},{"id":"MCQ-CB-100","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Vi sinh vật","q":"Trong quá trình cố định đạm sinh học ($N_2 + 8H^+ + 8e^- + 16\\text{ATP} \\rightarrow 2NH_3 + H_2 + 16\\text{ADP} + 16P_i$), enzyme Nitrogenase của vi khuẩn <i>Rhizobium</i> bị bất hoạt không thuận nghịch bởi phân tử khí $O_2$ tự do. Nốt sần rễ cây họ Đậu bảo vệ Nitrogenase bằng cơ chế nào?","opts":["Tổng hợp protein Leghemoglobin (hồng cầu thực vật) gắn chặt $O_2$ tự do, giữ nồng độ $O_2$ cực thấp vừa đủ cho hô hấp vi khuẩn mà không làm hỏng Nitrogenase.","Tăng cường quang phân ly nước ngay trong tế bào nốt sần để bơm thêm $O_2$.","Đẩy toàn bộ vi khuẩn <i>Rhizobium</i> ra bề mặt rễ tiếp xúc trực tiếp với không khí.","Chuyển hóa Nitrogenase thành RuBisCO."],"ans":0,"exp":"Leghemoglobin (phần globin do cây họ Đậu mã hóa, nhân heme do vi khuẩn tổng hợp) có ái lực rất cao với $O_2$, vừa điều tiết $O_2$ cho chuỗi hô hấp tạo 16 ATP, vừa che chắn bảo vệ Nitrogenase."},{"id":"MCQ-CB-101","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Virus","q":"Thuốc AZT (Azidothymidine) được sử dụng trong phác đồ điều trị HIV là chất tương tự Thymidine nhưng thay nhóm $3'-\\text{OH}$ bằng nhóm azido ($-N_3$). Enzyme nào của HIV là đích ức chế trực tiếp của AZT?","opts":["Enzyme Integrase cắt nối DNA.","Enzyme Protease cắt polyprotein HIV.","Enzyme Neuraminidase trên vỏ virus cúm.","Enzyme Phiên mã ngược (Reverse Transcriptase) của HIV."],"ans":3,"exp":"Reverse Transcriptase gắn nhầm AZT-triphosphate thay cho dTTP vào mạch cDNA đang tổng hợp; do thiếu đầu $3'-\\text{OH}$, quá trình kéo dài cDNA của HIV bị dừng ngay lập tức."},{"id":"MCQ-CB-102","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Virus","q":"Tại sao khi điều trị bệnh nhân nhiễm HIV bằng đơn trị liệu một loại thuốc kháng virus (ví dụ chỉ dùng AZT) thì sau một thời gian ngắn virus thường xuất hiện chủng kháng thuốc rất nhanh?","opts":["Do virus HIV có khả năng tiếp hợp trao đổi plasmid với vi khuẩn đường ruột.","Do tế bào lympho $T_H$ tự biến đổi thuốc AZT thành chất dinh dưỡng cho virus.","Do bộ gen của HIV là DNA mạch kép siêu bền có cơ chế sửa sai hoàn hảo.","Do enzyme phiên mã ngược (Reverse Transcriptase) của HIV không có hoạt tính sửa sai ($3'\\rightarrow 5'$ exonuclease) nên tốc độ đột biến cực cao, nhanh chóng tạo ra các biến thể kháng thuốc được chọn lọc tự nhiên giữ lại."],"ans":3,"exp":"Retrovirus như HIV có tỉ lệ sai sót sao chép cao gấp hàng nghìn lần DNA polymerase thông thường vì RT thiếu cơ chế đọc sửa, tạo nguồn biến dị di truyền khổng lồ."},{"id":"MCQ-CB-103","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Virus","q":"Tại sao việc phát triển vaccine phòng bệnh cúm mùa (Influenza A) đòi hỏi phải cập nhật chủng mới gần như hằng năm?","opts":["Do virus cúm không có bất kỳ kháng nguyên bề mặt nào.","Do cơ thể người không bao giờ tạo được tế bào nhớ B.","Do virus cúm có hệ gen DNA mạch kép không thay đổi.","Do virus cúm có hệ gen gồm 8 phân đoạn RNA mạch đơn dễ xảy ra cả 'trôi dạt kháng nguyên' (đột biến điểm HA, NA) lẫn 'chuyển dịch kháng nguyên' (tái tổ hợp phân đoạn RNA giữa các chủng khi đồng nhiễm)."],"ans":3,"exp":"Sự kết hợp giữa đột biến nhanh (antigenic drift) và trao đổi các đoạn RNA phân mảnh (antigenic shift) làm gai Hemagglutinin (H) và Neuraminidase (N) thay đổi liên tục."},{"id":"MCQ-CB-104","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hóa sinh Lipid","q":"Mặc dù 1 gam chất béo (Triglyceride) giải phóng năng lượng khoảng $9\\text{ kcal}$, cao gấp hơn 2 lần so với 1 gam Carbohydrate ($4\\text{ kcal}$), nhưng tại sao trong lúc chạy nước rút cường độ tối đa, cơ xương lại ưu tiên phân giải Glycogen thay vì Acid béo?","opts":["Vì tế bào cơ xương không có bất kỳ ti thể nào.","Vì oxy hóa hoàn toàn acid béo đòi hỏi nhiều $O_2$ hơn và tốc độ huy động qua ti thể chậm hơn nhiều so với đường phân phân giải nhanh Glucose/Glycogen (có thể tạo ATP ngay cả khi thiếu $O_2$).","Vì phân giải lipid không tạo ra bất kỳ phân tử ATP nào.","Vì Glycogen nằm tự do trong máu còn lipid chỉ có ở não."],"ans":1,"exp":"Glycogen phân giải tức thời qua đường phân ngay trong bào tương (kể cả kỵ khí) đáp ứng nhu cầu ATP bùng nổ tức thì, còn $\\beta$-oxy hóa acid béo hoàn toàn phụ thuộc $O_2$ và chuỗi truyền $e^-$."},{"id":"MCQ-CB-105","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hóa sinh Hóa học","q":"Trong phản ứng chuẩn độ pH của một amino acid trung tính (như Alanine), giá trị điểm đẳng điện ($pI$) là giá trị pH mà tại đó phân tử tồn tại chủ yếu ở dạng ion lưỡng cực (Zwitterion) có tổng điện tích bằng 0. Khi đặt Alanine trong dung dịch đệm có $pH = 11$ (cao hơn nhiều so với $pI \\approx 6.0$), nó sẽ di chuyển về cực nào trong điện trường?","opts":["Đứng yên tại điểm xuất phát vì luôn trung hòa điện.","Cực dương (Anode) vì ở môi trường kiềm $pH = 11$, nhóm $-NH_3^+$ nhường $H^+$ nên phân tử mang điện tích âm thuần ($-COO^-$).","Kết tủa hoàn toàn thành khí Amoniac.","Cực âm (Cathode) vì phân tử tích điện dương."],"ans":1,"exp":"Ở $pH > pI$, nồng độ $H^+$ thấp khiến amino acid bị khử proton ở cả nhóm $-COOH$ và $-NH_3^+$, mang điện tích âm thuần và bị hút về cực dương."},{"id":"MCQ-CB-106","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Kỹ thuật tế bào","q":"Kỹ thuật kháng thể đơn dòng (Monoclonal antibody) tạo ra tế bào lai Hybridoma bằng cách dung hợp tế bào nào với tế bào nào?","opts":["Dung hợp tế bào Lympho B bình thường (có khả năng tiết 1 loại kháng thể đặc hiệu nhưng sống ngắn ngày) với tế bào u tủy Myeloma (bất tử nhưng không tiết kháng thể).","Dung hợp tế bào phôi với hạt phấn cây lúa.","Dung hợp tế bào hồng cầu trưởng thành với tế bào vi khuẩn <i>E. coli</i>.","Dung hợp tế bào Lympho $T_C$ với tế bào thần kinh."],"ans":0,"exp":"Tế bào lai Hybridoma thừa hưởng khả năng sản xuất một loại kháng thể đặc hiệu từ tế bào B và khả năng phân chia bất tử từ tế bào u tủy (chọn lọc trên môi trường HAT)."},{"id":"MCQ-CB-107","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Màng & Bào quan","q":"Trong một thí nghiệm, người ta đánh dấu huỳnh quang đỏ các protein màng của tế bào chuột và huỳnh quang xanh các protein màng của tế bào người, sau đó dung hợp hai tế bào thành tế bào lai. Sau 40 phút ủ ở $37^\\circ\\text{C}$, các chấm đỏ và xanh phân bố xen kẽ đồng đều khắp bề mặt tế bào lai. Thí nghiệm kinh điển (Frye - Edidin) này chứng minh điều gì?","opts":["Màng sinh chất người và chuột không chứa lipid.","Tính khảm động (Fluidity): các phân tử protein màng có khả năng khuếch tán chuyển động ngang trong mặt phẳng lớp kép phospholipid.","Protein màng gắn cố định tuyệt đối như gạch xây tường.","Lớp kép phospholipid liên tục lật từ mặt ngoài vào mặt trong (flip-flop) mỗi giây."],"ans":1,"exp":"Khi hạ nhiệt độ xuống $0^\\circ\\text{C}$, sự trộn lẫn bị dừng lại chứng tỏ tốc độ khuếch tán ngang của protein phụ thuộc vào độ lỏng của lớp kép phospholipid."},{"id":"MCQ-CB-108","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cấu trúc tế bào","q":"Ở tế bào thực vật, quá trình tổng hợp các sợi Cellulose cấu tạo nên thành tế bào sơ cấp diễn ra trực tiếp tại vị trí nào nhờ phức hợp enzyme Cellulose synthase (dạng hoa hồng)?","opts":["Tại lưới nội chất trơn.","Trong lòng nhân tế bào.","Bên trong chất nền của Lục lạp.","Ngay trên bề mặt ngoài của màng sinh chất (được định hướng bởi các vi ống vỏ nằm sát mặt trong màng)."],"ans":3,"exp":"Khác với Pectin và Hemicellulose (được tổng hợp ở Golgi và xuất bào), Cellulose được tổng hợp trực tiếp tại phức hợp hoa hồng Cellulose synthase trên màng sinh chất."},{"id":"MCQ-CB-109","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cấu trúc tế bào","q":"Nếu đột ngột xử lý tế bào tuyến giáp đang tổng hợp hormone protein bằng một chất ức chế đặc hiệu hoàn toàn quá trình gắn nhóm đường (Glycosylation) trong lưới nội chất hạt và bộ máy Golgi, hậu quả phổ biến nào xảy ra với các protein màng và protein tiết?","opts":["Quá trình phiên mã DNA thành mRNA tăng gấp 10 lần.","Tế bào chuyển sang sử dụng thành Peptidoglycan.","Nhiều protein bị gấp cuộn sai, bị giữ lại phân hủy trong ER hoặc mất ổn định, không định hướng được ra màng sinh chất hay ngoại bào.","Tất cả protein chuyển sang tổng hợp trong nhân tế bào."],"ans":2,"exp":"Chuỗi oligosaccharide gắn trên protein giúp tăng độ tan, chống phân giải bởi protease, hỗ trợ gấp cuộn đúng trong ER (hệ Calnexin) và làm tín hiệu định tuyến tại Golgi."},{"id":"MCQ-CB-110","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hô hấp tế bào","q":"Ở một số mô động vật sơ sinh và động vật ngủ đông (như chuột, gấu), mô mỡ nâu (Brown adipose tissue) rất phát triển và giàu ti thể. Protein UCP1 (Thermogenin) trên màng trong ti thể tế bào mỡ nâu hoạt động như một 'chất phá ghép tự nhiên' để làm gì?","opts":["Dự trữ tinh bột thay cho mỡ trắng.","Ngăn cản hoàn toàn chu trình Krebs và chuỗi truyền electron.","Mở kênh cho $H^+$ tràn trở lại chất nền ti thể không qua ATP synthase, chuyển trực tiếp năng lượng gradient điện hóa thành nhiệt năng sưởi ấm cơ thể.","Tổng hợp gấp 10 lần lượng ATP để co cơ chạy trốn."],"ans":2,"exp":"UCP1 (Uncoupling protein 1) tạo con đường rò rỉ $H^+$ có kiểm soát giúp sinh nhiệt không rung cơ (Non-shivering thermogenesis) cực kỳ quan trọng ở trẻ sơ sinh và thú ngủ đông."},{"id":"MCQ-CB-111","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Enzyme","q":"Một số enzyme tiêu hóa nguy hiểm như Trypsinogen hay Pepsinogen được tiết ra dưới dạng tiền enzyme bất hoạt (Zymogen) và chỉ được hoạt hóa sau khi đi vào khoang ruột hoặc khoang dạ dày. Ý nghĩa sinh học của cơ chế này là gì?","opts":["Giúp enzyme tiết kiệm nguyên liệu amino acid.","Làm tăng năng lượng hoạt hóa của phản ứng thủy phân.","Bảo vệ chính các tế bào tuyến tụy và tế bào thành dạ dày khỏi bị các enzyme tiêu hóa tự phân hủy (tự tiêu).","Giúp enzyme chuyển từ cấu trúc bậc 4 sang cấu trúc bậc 1."],"ans":2,"exp":"Nếu Trypsin hoạt động ngay trong tế bào tụy ngoại tiết, nó sẽ kích hoạt hàng loạt protease khác gây viêm tụy cấp hoại tử. Chỉ ở ruột non, Enterokinase mới cắt hoạt hóa Trypsinogen thành Trypsin."},{"id":"MCQ-CB-112","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quang hợp tế bào","q":"Trong thí nghiệm tách chiết sắc tố quang hợp từ lá xanh bằng dung môi hữu cơ acetone, khi chiếu tia sáng trắng vào ống nghiệm chứa dung dịch Diệp lục đã tách rời khỏi màng Thylakoid, ta thấy dung dịch phát ra ánh sáng huỳnh quang màu đỏ thẫm. Vì sao ở lá cây sống bình thường hiện tượng phát huỳnh quang này rất yếu?","opts":["Vì trong màng Thylakoid nguyên vẹn, năng lượng kích thích của electron ở Diệp lục được truyền nhanh sang chất nhận electron sơ cấp để tạo ATP và NADPH, thay vì tỏa nhiệt và phát huỳnh quang.","Vì trong lá sống không có tia sáng xanh tím.","Vì trong lá sống Diệp lục ở trạng thái tinh thể rắn.","Vì nước trong tế bào lá hấp thụ hết ánh sáng đỏ."],"ans":0,"exp":"Khi tách chiết phá vỡ quang hệ, electron nhảy lên mức năng lượng cao không có chất nhận electron sơ cấp đón nhận nên rơi trở về trạng thái cơ bản, giải phóng năng lượng dưới dạng nhiệt và photon huỳnh quang đỏ."},{"id":"MCQ-CB-113","topic":"cellbio","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Truyền tin tế bào","q":"Khí Nitric Oxide ($\\text{NO}$) là một phân tử khí nhỏ do tế bào nội mô mạch máu tiết ra để làm giãn cơ trơn thành mạch máu (nguyên lý của thuốc Nitroglycerin trị đau thắt ngực). $\\text{NO}$ tác động qua cơ chế nào?","opts":["Kích thích bơm $Na^+/K^+$ bơm ngược $Na^+$ vào tế bào.","Đi vào nhân cắt đứt gen mã hóa Actin và Myosin.","Gắn vào thụ thể GPCR ở mặt ngoài màng và đóng kênh $K^+$.","Khuếch tán trực tiếp qua màng tế bào cơ trơn và hoạt hóa enzyme Guanylyl cyclase nội bào để tạo chất truyền tin thứ hai là cGMP gây giãn cơ."],"ans":3,"exp":"Khí $\\text{NO}$ có thời gian bán hủy chỉ vài giây, đi qua màng trực tiếp hoạt hóa Guanylyl cyclase $\\rightarrow$ chuyển GTP thành cGMP $\\rightarrow$ kích hoạt PKG làm giãn cơ trơn mạch máu."},{"id":"MCQ-CB-114","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hô hấp Ti thể","q":"Ti thể cô lập được cung cấp đầy đủ Pyruvate, Malate, ADP, $P_i$ và $O_2$. Tại thời điểm $t_1$, bổ sung thêm chất độc Antimycin A (ức chế đặc hiệu phức hợp III). Nếu tại thời điểm $t_2$, người ta bổ sung thêm chất cho electron nhân tạo là Ascorbate + TMPD (chuyển thẳng electron vào Cytochrome c), tốc độ tiêu thụ $O_2$ và tổng hợp ATP sau $t_2$ sẽ diễn biến như thế nào?","opts":["Cả tiêu thụ $O_2$ và tạo ATP đều giữ nguyên bằng 0 vì Phức hợp III đã bị khóa.","Tiêu thụ $O_2$ tăng vọt vượt mức bình thường do bị phá ghép.","Tốc độ tiêu thụ $O_2$ phục hồi nhưng tuyệt đối không có ATP nào được tạo ra.","Chuỗi truyền $e^-$ từ Cytochrome c qua Phức hợp IV tới $O_2$ được khôi phục; cả tốc độ tiêu thụ $O_2$ và tổng hợp ATP (nhờ $H^+$ bơm tại Phức hợp IV) đều phục hồi trở lại một phần."],"ans":3,"exp":"Antimycin A chặn Phức hợp III. Khi cấp Ascorbate + TMPD nhường $e^-$ trực tiếp cho Cytochrome c, Phức hợp IV (Cytochrome c oxidase) vẫn nhận $e^-$, khử $O_2$ thành $H_2O$ và tiếp tục bơm $H^+$ tạo gradient để ATP synthase tổng hợp ATP."},{"id":"MCQ-CB-115","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hô hấp Ti thể","q":"Khi bổ sung hợp chất Atractyloside (chất ức chế đặc hiệu protein trao đổi Adenine nucleotide translocase - ANT nằm trên màng trong ti thể, ngăn không cho ATP đi ra ngoài và ADP đi vào chất nền ti thể) vào hệ thống ti thể đang hô hấp mạnh, điều gì sẽ xảy ra?","opts":["Màng trong ti thể bị thủng làm rò rỉ $H^+$ giống 2,4-DNP.","Chuỗi truyền điện tử và tiêu thụ $O_2$ tăng vọt lên mức cực đại.","Đường phân trong bào tương bị ức chế ngay do quá dư thừa ATP ở bào tương.","Nồng độ ADP trong chất nền ti thể cạn kiệt nhanh chóng làm ATP synthase dừng quay, gây ứ đọng $H^+$ ở xoang gian màng và làm giảm mạnh tốc độ tiêu thụ $O_2$."],"ans":3,"exp":"Không có ADP nhập vào chất nền ti thể, ATP synthase ngừng tổng hợp ATP giống như bị khóa bởi Oligomycin $\\rightarrow$ proton $H^+$ ứ đọng kìm hãm chuỗi truyền electron và giảm tiêu thụ $O_2$."},{"id":"MCQ-CB-116","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hô hấp Ti thể","q":"Độc tố Carbon monoxide ($\\text{CO}$) và Cyanide ($\\text{CN}^-$) đều gây ngộ độc tế bào cực nhanh và tử vong. Trong đó, giải độc $\\text{CN}^-$ bằng tiêm Nitrite (biến Hemoglobin thành Methemoglobin chứa $Fe^{3+}$) dựa trên cơ sở hóa sinh nào?","opts":["$Fe^{3+}$ của Methemoglobin có ái lực cao cạnh tranh bắt giữ $\\text{CN}^-$ trong máu thành Cyanmethemoglobin, giải cứu nhóm $Fe^{3+}$ tại Phức hợp IV (Cytochrome c oxidase) trong ti thể.","Nitrite đóng vai trò chất phá ghép thay thế Phức hợp IV.","Methemoglobin vận chuyển được lượng $O_2$ gấp 4 lần Hemoglobin bình thường.","Methemoglobin trực tiếp chuyển hóa $\\text{CN}^-$ thành Glucose."],"ans":0,"exp":"$\\text{CN}^-$ gắn chặt vào ion $Fe^{3+}$ của nhân heme $a_3$ trong Phức hợp IV. Tạo lượng nhỏ Methemoglobin ($Fe^{3+}$) trong máu giúp 'bẫy' $\\text{CN}^-$ kéo nó ra khỏi Phức hợp IV trước khi dùng Thiosulfate giải độc thành Thiocyanate."},{"id":"MCQ-CB-117","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Động học Enzyme","q":"Trong một thử nghiệm động học enzyme có mặt chất ức chế X, người ta đo thấy cả giá trị $V_{\\max}$ và giá trị $K_m$ biểu kiến đều giảm đi theo đúng một tỉ lệ (ví dụ cả $V_{\\max}$ và $K_m$ đều giảm một nửa, hai đường thẳng trên đồ thị Lineweaver-Burk song song với nhau). Chất X thuộc kiểu ức chế nào?","opts":["Ức chế phi cạnh tranh (Uncompetitive inhibition): chất X chỉ gắn đặc hiệu vào phức hợp Enzyme-Cơ chất ($ES$) chứ không gắn vào enzyme tự do ($E$).","Hoạt hóa dị lập thể.","Ức chế cạnh tranh thuần túy.","Ức chế không cạnh tranh thuần túy ($K_m$ giữ nguyên)."],"ans":0,"exp":"Chất ức chế phi cạnh tranh khóa phức hợp $ES \\rightarrow ESI$, làm giảm nồng độ $ES$ hiệu dụng ($V_{\\max}$ giảm) đồng thời kéo cân bằng $E + S \\rightleftharpoons ES$ sang phải nên làm $K_m$ biểu kiến giảm cùng tỉ lệ (đường Lineweaver-Burk song song)."},{"id":"MCQ-CB-118","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Động học Enzyme","q":"Một loại thuốc X có khả năng gắn cộng hóa trị bền vững với gốc Serine thiết yếu tại trung tâm hoạt động của enzyme Acetylcholinesterase (giống cơ chế của khí độc thần kinh Sarin). Trong thực nghiệm động học, nếu tăng nồng độ cơ chất Acetylcholine lên gấp 1000 lần thì hoạt tính enzyme có phục hồi lại tốc độ $V_{\\max}$ ban đầu hay không?","opts":["Có, thậm chí $V_{\\max}$ tăng lên gấp đôi.","Không, vì X là chất ức chế KHÔNG thuận nghịch (cộng hóa trị) làm giảm vĩnh viễn số lượng phân tử enzyme hoạt động hiệu dụng ($V_{\\max}$ giảm mạnh).","Không, nhưng $K_m$ tăng lên vô cùng còn $V_{\\max}$ giữ nguyên.","Có, vì mọi chất gắn vào trung tâm hoạt động đều cạnh tranh thuận nghịch."],"ans":1,"exp":"Chất ức chế không thuận nghịch tạo liên kết cộng hóa trị khóa vĩnh viễn trung tâm hoạt động nên làm giảm nồng độ enzyme hoạt động $[E]_T$, dẫn đến $V_{\\max}$ giảm và không thể đảo ngược bằng cách tăng $[S]$."},{"id":"MCQ-CB-119","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Động học Enzyme","q":"Một enzyme $E$ xúc tác phản ứng với $K_m = 5 \\times 10^{-5}\\text{ M}$ và $[E]_T = 10^{-8}\\text{ M}$. Khi $[S] = 0.05\\text{ M}$ (bão hòa cơ chất), tốc độ phản ứng đo được là $v = 2 \\times 10^{-4}\\text{ M/s}$. Số vòng quay xúc tác (Turnover number, $k_{\\text{cat}}$) của enzyme này bằng bao nhiêu?","opts":["$10^4\\text{ s}^{-1}$.","$2 \\times 10^6\\text{ s}^{-1}$.","$5 \\times 10^3\\text{ s}^{-1}$.","$2 \\times 10^4\\text{ s}^{-1}$."],"ans":3,"exp":"Do $[S] = 0.05\\text{ M} \\gg K_m = 5 \\times 10^{-5}\\text{ M}$, tốc độ đo được xấp xỉ $V_{\\max} = 2 \\times 10^{-4}\\text{ M/s}$. Suy ra $k_{\\text{cat}} = \\frac{V_{\\max}}{[E]_T} = \\frac{2 \\times 10^{-4}}{10^{-8}} = 2 \\times 10^4\\text{ s}^{-1}$."},{"id":"MCQ-CB-120","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Truyền tin tế bào","q":"Độc tố ho gà (Pertussis toxin) từ vi khuẩn <i>Bordetella pertussis</i> xúc tác phản ứng ADP-ribosyl hóa tiểu phần $\\alpha$ của G-protein ức chế ($G_i$), khóa chặt $G_i$ ở trạng thái gắn GDP bất hoạt (không thể ức chế Adenylyl cyclase). Khi tế bào niêm mạc khí quản nhiễm độc tố ho gà, điều gì xảy ra với nồng độ cAMP?","opts":["Nồng độ cAMP giảm xuống bằng 0 vì Adenylyl cyclase bị phá hủy.","$G_i$ mất khả năng ức chế Adenylyl cyclase nên nồng độ cAMP nội bào tăng vọt bất thường ngay cả khi có tín hiệu ức chế.","$G_s$ bị khóa hoàn toàn ở trạng thái gắn GDP.","Kênh $Na^+$ cổng điện thế bị khóa vĩnh viễn."],"ans":1,"exp":"Khác với độc tố tả (khóa $G_s$ ở trạng thái BẬT liên tục), độc tố ho gà khóa $G_i$ ở trạng thái TẮT liên tục — mất phanh hãm Adenylyl cyclase nên cũng gây tăng cao cAMP."},{"id":"MCQ-CB-121","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Truyền tin tế bào","q":"Trong hệ thống truyền tin tế bào, protein G đơn phân nhỏ (như $\\text{Ras}$) đóng vai trò công tắc phân tử chuyển tín hiệu từ thụ thể RTK sang dòng thác MAPK. Nếu một đột biến điểm ở gen <i>Ras</i> làm mất hoạt tính tự thủy phân GTP thành GDP (GTPase) của protein Ras, hậu quả ở mức tế bào là gì?","opts":["Protein Ras bị kẹt vĩnh viễn ở trạng thái bất hoạt nên tế bào chết theo Apoptosis.","Thụ thể RTK không thể dimer hóa khi có yếu tố tăng trưởng.","Protein Ras bị kẹt vĩnh viễn ở trạng thái 'BẬT' (gắn GTP), kích thích liên tục dòng thác MAPK thúc đẩy tế bào phân chia mất kiểm soát dẫn đến ung thư.","Tế bào mất khả năng tổng hợp mRNA."],"ans":2,"exp":"Đột biến khóa Ras ở trạng thái gắn GTP biến Proto-oncogene <i>Ras</i> thành Oncogene hoạt động tự trị không cần tín hiệu tăng trưởng từ bên ngoài."},{"id":"MCQ-CB-122","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Truyền tin tế bào","q":"Thụ thể hạt nhân (Nuclear receptor) đối với hormone Tuyến giáp ($T_3$) bình thường luôn nằm sẵn trong nhân tế bào và gắn lên vùng trình tự đáp ứng (TRE) trên DNA ngay cả khi chưa có mặt hormone $T_3$. Khi KHÔNG có $T_3$, thụ thể này thực hiện chức năng gì đối với gen đích?","opts":["Cắt đứt DNA tại vùng TRE.","Chuyển ra ngoài màng sinh chất hoạt động như GPCR.","Phiên mã liên tục gen đích ở tốc độ cực đại ngay cả khi không có $T_3$.","Tuyển mộ các phức hợp đồng ức chế (như HDAC - khử acetyl histone) để đóng xoắn chromatin và KÌM HÃM phiên mã; khi có $T_3$ gắn vào, thụ thể đổi cấu hình đẩy HDAC ra và gọi phức hợp HAT để KÍCH HOẠT phiên mã."],"ans":3,"exp":"Thụ thể $T_3$ và Acid Retinoic là thụ thể nhân loại II: không có phối tử chúng đóng vai trò chất ức chế phiên mã (gọi HDAC); gắn phối tử làm lộ miền kích hoạt gọi HAT/co-activator."},{"id":"MCQ-CB-123","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Màng sinh chất","q":"Hai bên màng sinh chất của tế bào biểu mô ruột có sự phân bố bất đối xứng nghiêm trọng giữa hai lớp lá phospholipid: Phosphatidylserine (PS - mang điện tích âm) bình thường chỉ nằm ở lá mặt TRONG hướng vào bào tương nhờ enzyme Flippase (tiêu tốn ATP). Khi tế bào bước vào giai đoạn sớm của Apoptosis, enzyme Scramblase được hoạt hóa làm PS lộ ra mặt NGOÀI màng. Ý nghĩa sinh học của sự lộ PS ra mặt ngoài là gì?","opts":["Đóng vai trò tín hiệu 'hãy ăn tôi' (eat-me signal) để đại thực bào nhận diện và nuốt gọn tế bào đang chết theo chương trình mà không gây viêm.","Kích thích tế bào phân chia nguyên phân nhanh gấp đôi.","Làm màng tế bào trở nên không thấm đối với $O_2$ và $CO_2$.","Trung hòa hoàn toàn điện tích của bơm $Na^+/K^+$."],"ans":0,"exp":"Bình thường Flippase giữ PS ở mặt trong; khi Apoptosis xảy ra, Flippase bị bất hoạt bởi Caspase và Scramblase đảo PS ra mặt ngoài để thụ thể trên đại thực bào nhận biết."},{"id":"MCQ-CB-124","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Màng sinh chất","q":"Nghiên cứu tốc độ vận chuyển chất X và chất Y qua màng sinh chất theo nồng độ bên ngoài $[C]_{\\text{ngoài}}$ cho thấy: Tốc độ thấm chất X tăng tuyến tính mãi không bão hòa khi tăng $[C]_{\\text{ngoài}}$; tốc độ vận chuyển chất Y tăng nhanh lúc đầu nhưng tiến tới mức bão hòa $V_{\\max}$ ở nồng độ cao, và bị ức chế khi hạ nhiệt độ hoặc thêm chất cấu trúc gần giống Y. Chất X và chất Y được vận chuyển qua màng theo cơ chế nào?","opts":["Chất X: Vận chuyển tích cực dùng ATP; Chất Y: Khuếch tán đơn giản.","Chất X: Khuếch tán đơn giản qua lớp kép phospholipid; Chất Y: Khuếch tán tăng cường qua protein mang (Carrier) hoặc vận chuyển tích cực qua bơm.","Chất X: Nhập bào; Chất Y: Khuếch tán đơn giản.","Cả X và Y đều đi qua kênh Aquaporin."],"ans":1,"exp":"Đặc điểm động học bão hòa kiểu Michaelis-Menten ($V_{\\max}$) và tính cạnh tranh đặc hiệu chứng tỏ có sự tham gia của protein mang/vận chuyển có số lượng giới hạn trên màng."},{"id":"MCQ-CB-125","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Vận chuyển màng","q":"Giả sử một tế bào động vật có nồng độ $K^+$ nội bào gấp 30 lần ngoại bào ($150\\text{ mM}$ trong / $5\\text{ mM}$ ngoài) và điện thế màng lúc nghỉ là $-70\\text{ mV}$ (mặt trong âm hơn mặt ngoài). Biết điện thế cân bằng Nernst của $K^+$ là $E_K = -90\\text{ mV}$. Nếu đột ngột mở thêm rất nhiều kênh rò rỉ $K^+$ trên màng, ion $K^+$ sẽ di chuyển theo chiều nào?","opts":["$K^+$ hoàn toàn không di chuyển vì đang ở thế cân bằng.","$K^+$ kéo theo Glucose đi ra ngoài tế bào.","$K^+$ đi từ NGOÀI vào TRONG tế bào làm khử cực màng.","$K^+$ đi từ TRONG ra NGOÀI tế bào (do lực đẩy hóa học hướng ra ngoài mạnh hơn lực hút tĩnh điện vào trong), làm điện thế màng tiến dần về $-90\\text{ mV}$ (tăng phân cực)."],"ans":3,"exp":"Lực điện hóa tác dụng lên $K^+$ tỉ lệ với $(V_m - E_K) = (-70) - (-90) = +20\\text{ mV} > 0$, đẩy ion dương $K^+$ thoát ra ngoài cho đến khi $V_m$ tiệm cận $E_K = -90\\text{ mV}$."},{"id":"MCQ-CB-126","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bào quan & Thí nghiệm","q":"Các nhà khoa học tổng hợp một protein lai gồm đoạn trình tự tín hiệu dẫn đường vào Ti thể (MTS - giàu amino acid tích điện dương) gắn vào đầu N của protein huỳnh quang xanh (GFP - vốn bình thường nằm ở bào tương), rồi đưa vào tế bào. Nếu đột ngột xử lý tế bào bằng chất phá ghép FCCP (làm triệt tiêu điện thế màng và gradient $H^+$ qua màng trong ti thể), protein lai MTS-GFP sẽ tập trung ở đâu?","opts":["Được chuyển hướng vào trong lòng nhân tế bào.","Không thể nhập vào chất nền ti thể (vì mất điện thế màng $\\Delta\\Psi$ cần thiết để kéo trình tự tín hiệu dương qua phức hợp TIM23) nên bị ứ đọng lại ở bào tương hoặc kẹt ở màng ngoài.","Được xuất bào toàn bộ ra môi trường ngoại bào.","Đi vào chất nền ti thể nhanh gấp 5 lần bình thường."],"ans":1,"exp":"Vận chuyển protein qua màng trong ti thể (phức hợp TIM23) đòi hỏi điện thế màng $\\Delta\\Psi$ âm phía chất nền ti thể để kéo chuỗi dẫn MTS tích điện dương và cần ATP cho mtHsp70 kéo vào."},{"id":"MCQ-CB-127","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Bào quan & Đường tiết","q":"Trong thí nghiệm về cơ chế định tuyến protein của tế bào nấm men đột biến nhạy nhiệt độ ($sec$ mutants): Ở nhiệt độ $37^\\circ\\text{C}$, chủng đột biến $secA$ bị ứ đọng protein tiết chưa gắn thêm đường phức tạp ở trong lòng Lưới nội chất hạt (RER); chủng đột biến $secB$ bị ứ đọng túi tiết chứa protein hoàn chỉnh sát ngay dưới màng sinh chất. Nhận định nào sau đây là chính xác?","opts":["Đột biến $secA$ làm hỏng bước nảy chồi túi vận chuyển từ RER sang Golgi (COPII); đột biến $secB$ làm hỏng bước hòa màng xuất bào (SNARE) tại màng sinh chất.","Đột biến $secA$ xảy ra sau bước xuất bào.","Cả hai đột biến đều làm hỏng bơm $H^+$ của Lysosome.","Đột biến $secA$ làm hỏng quá trình dịch mã trên ribosome tự do; đột biến $secB$ làm hỏng quá trình phiên mã."],"ans":0,"exp":"Con đường tiết đi theo thứ tự RER $\\xrightarrow{\\text{COPII}}$ Golgi $\\xrightarrow{\\text{túi tiết}}$ hòa màng sinh chất (SNARE). Chủng $secA$ tắc ở bước đầu rời ER; chủng $secB$ tắc ở bước cuối hòa màng xuất bào."},{"id":"MCQ-CB-128","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hô hấp & Quang hợp","q":"Khi so sánh phức hợp ATP synthase ở Màng trong ti thể ($F_0 F_1$) và ở Màng Thylakoid lục lạp ($CF_0 CF_1$), phát biểu nào sau đây mô tả đúng vị trí của đầu $F_1 / CF_1$ (nơi trực tiếp tổng hợp ATP) và hướng dòng chảy $H^+$ sinh tổng hợp ATP?","opts":["Ở lục lạp, $H^+$ được bơm từ lòng Thylakoid ra Stroma nhờ năng lượng ánh sáng rồi chảy ngược lại để tạo ATP.","Ở cả hai bào quan, ATP đều được tổng hợp bên trong khoang hẹp có pH thấp.","Ở ti thể: đầu $F_1$ quay vào Xoang gian màng; Ở lục lạp: đầu $CF_1$ quay vào Lòng Thylakoid.","Ở ti thể: $H^+$ chảy từ Xoang gian màng vào Chất nền (Matrix), đầu $F_1$ quay vào Matrix; Ở lục lạp: $H^+$ chảy từ Lòng Thylakoid ra Chất nền Stroma, đầu $CF_1$ quay ra Stroma."],"ans":3,"exp":"Trong cả hai bào quan, các phân tử ATP được tổng hợp tại đầu xúc tác $F_1/CF_1$ hướng về phía chất nền có độ pH cao hơn (Matrix của ti thể và Stroma của lục lạp), nơi diễn ra chu trình Krebs và chu trình Calvin."},{"id":"MCQ-CB-129","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quang hợp tế bào","q":"Trong một thí nghiệm, lục lạp tách rời được chiếu sáng mạnh trong môi trường chứa $H_2^{18}\\text{O}$, $CO_2$ bình thường, $ADP, P_i$ và $NADP^+$. Kết thúc thí nghiệm, đồng vị nặng $^{18}\\text{O}$ sẽ xuất hiện trực tiếp trong sản phẩm nào?","opts":["Không xuất hiện ở bất kỳ sản phẩm nào vì $H_2^{18}\\text{O}$ không bị quang phân ly.","Chỉ có trong khí $O_2$ giải phóng ra ($^{18}\\text{O}_2$), không xuất hiện trong phân tử đường Glucose mới tạo thành.","Chỉ xuất hiện trong phân tử đường Glucose, không có trong khí $O_2$.","Xuất hiện đều ở cả khí $O_2$ và phân tử Glucose."],"ans":1,"exp":"Toàn bộ nguyên tử O của $O_2$ quang hợp lấy từ nước; còn nguyên tử O trong Glucose và trong nước sinh ra ở pha tối lấy từ $CO_2$."},{"id":"MCQ-CB-130","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quang hợp tế bào","q":"Bằng chứng thực nghiệm nào (do Robert Emerson phát hiện - 'Hiệu ứng tăng cường Emerson') đã chứng minh thực vật bậc cao phải có HAI quang hệ khác nhau (PSI và PSII) phối hợp hoạt động nối tiếp nhau?","opts":["Tốc độ quang hợp khi chiếu ĐỒNG THỜI ánh sáng đỏ ($680\\text{ nm}$) và ánh sáng đỏ xa ($700\\text{ nm}$) lớn hơn rất nhiều so với tổng tốc độ quang hợp khi chiếu riêng rẽ từng bước sóng.","Ánh sáng xanh lục cho hiệu suất quang hợp cao nhất.","Quang hợp vẫn tạo ra $O_2$ mạnh khi chỉ chiếu bước sóng $> 700\\text{ nm}$.","Cây chỉ quang hợp được vào ban đêm khi đóng khí khổng."],"ans":0,"exp":"Bước sóng $>680\\text{ nm}$ chỉ kích thích được PSI ($P_{700}$) mà không kích thích đủ PSII ($P_{680}$), nên hiệu suất giảm mạnh ('sụt đỏ'); khi bổ sung tia $650-680\\text{ nm}$ cả hai quang hệ chạy đồng bộ tạo hiệu ứng cộng hưởng."},{"id":"MCQ-CB-131","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quang hợp tế bào","q":"Vì sao trong điều kiện cường độ ánh sáng rất mạnh và nhiệt độ cao, nếu thiếu hụt dòng $CO_2$ hoặc bị tắc chuỗi chu trình Calvin (hết $NADP^+$ nhận $e^-$), các phân tử Diệp lục dễ bị hư hại bởi oxy hóa quang học (Photoinhibition)?","opts":["Electron năng lượng cao từ Diệp lục kích thích chuyển trực tiếp sang phân tử $O_2$ tạo các gốc tự do oxy hóa mạnh (ROS như $^{1}O_2, O_2^{\\bullet-}$) phá hủy protein D1 của Quang hệ II; các sắc tố Carotenoid giúp dập tắt năng lượng dư thừa này (làm nguội không phát quang - NPQ).","Quá nhiều $NADPH$ trực tiếp thủy phân màng kép lục lạp.","Ánh sáng mạnh làm đóng băng nước trong xoang Thylakoid.","Enzyme RuBisCO cắt đứt phân tử Diệp lục."],"ans":0,"exp":"Carotenoid (đặc biệt chu trình Xanthophyll: Violaxanthin $\\rightarrow$ Zeaxanthin) bảo vệ bộ máy quang hợp bằng cách tiêu tán năng lượng kích thích dư thừa thành nhiệt và trung hòa oxy đơn bội."},{"id":"MCQ-CB-132","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hóa sinh Nucleic acid","q":"Biết rằng một đoạn DNA mạch kép thẳng có $T_m$ (nhiệt độ nóng chảy, tại đó $50\\%$ DNA tách thành mạch đơn) tăng tuyến tính theo hàm lượng $G-C$. Khi tiến hành đo đường cong nóng chảy (độ hấp thụ tia UV ở bước sóng $260\\text{ nm}$ theo nhiệt độ) đối với 4 mẫu DNA có cùng chiều dài nhưng tỉ lệ phần trăm $A$ khác nhau: Mẫu 1 ($A=15\\%$), Mẫu 2 ($A=20\\%$), Mẫu 3 ($A=30\\%$), Mẫu 4 ($A=35\\%$). Thứ tự nhiệt độ nóng chảy $T_m$ tăng dần từ thấp đến cao của 4 mẫu là:","opts":["Mẫu 1 $<$ Mẫu 2 $<$ Mẫu 3 $<$ Mẫu 4.","Cả 4 mẫu có $T_m$ bằng nhau tuyệt đối vì cùng chiều dài.","Mẫu 4 $<$ Mẫu 3 $<$ Mẫu 2 $<$ Mẫu 1.","Mẫu 2 $<$ Mẫu 4 $<$ Mẫu 1 $<$ Mẫu 3."],"ans":2,"exp":"Cặp $G-C$ có 3 liên kết H và tương tác xếp chồng base mạnh hơn cặp $A-T$ (2 liên kết H). Phần trăm $A$ càng lớn thì $\\%G+C$ càng nhỏ $\\Rightarrow T_m$ càng thấp: Mẫu 4 ($30\\% G+C$) $<$ Mẫu 3 ($40\\%$) $<$ Mẫu 2 ($60\\%$) $<$ Mẫu 1 ($70\\%$)."},{"id":"MCQ-CB-133","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hóa sinh Protein","q":"Tình huống nào sau đây là ví dụ của hiện tượng biến tính protein CÓ KHẢ NĂNG hồi tính (Renaturation) thành công trong thí nghiệm nổi tiếng của Christian Anfinsen với enzyme Ribonuclease A (RNase A)?","opts":["Xử lý RNase A bằng Ure $8\\text{ M}$ và $\\beta$-mercaptoethanol (phá vỡ liên kết H và cầu disulfide $-S-S-$ làm mất hoạt tính), sau đó thẩm tách loại bỏ cả hai hóa chất này trong môi trường oxy hóa nhẹ thì enzyme tự gấp cuộn lại và phục hồi gần $100\\%$ hoạt tính.","Thủy phân RNase A bằng Trypsin thành hàng chục đoạn peptide ngắn rồi trộn lại.","Phá hủy hoàn toàn cấu trúc bậc 1 bằng HCl đặc $6\\text{ N}$ ở $110^\\circ\\text{C}$.","Đun sôi lòng trắng trứng ở $100^\\circ\\text{C}$ trong 30 phút rồi làm lạnh."],"ans":0,"exp":"Thí nghiệm Anfinsen chứng minh toàn bộ thông tin quy định cấu trúc không gian 3D tự nhiên của một protein đơn phân nằm ngay trong trình tự amino acid (cấu trúc bậc 1) của nó."},{"id":"MCQ-CB-134","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Vi sinh vật","q":"Nếu bổ sung đồng thời HAI nguồn đường là Glucose và Lactose vào môi trường nuôi cấy vi khuẩn <i>E. coli</i>, đồ thị sinh trưởng của quần thể theo thời gian sẽ xuất hiện hiện tượng 'sinh trưởng kép' (Diauxic growth: tăng theo pha log lần 1 $\\rightarrow$ pha lag ngắn $\\rightarrow$ tăng pha log lần 2). Nguyên nhân phân tử của pha lag ngắn ở giữa hai pha tăng trưởng là gì?","opts":["Khi Glucose vừa cạn kiệt, vi khuẩn mới bắt đầu tăng mạnh nồng độ $cAMP$ nội bào để phức hợp $CAP-cAMP$ kích hoạt phiên mã mạnh Operon Lac, tổng hợp các enzyme tiêu hóa Lactose trước khi tiếp tục phân chia.","Do vi khuẩn đột biến chuyển từ hiếu khí sang kỵ khí bắt buộc.","Do Lactose ức chế DNA polymerase ở pha đầu.","Do vi khuẩn chết hết ở pha 1 và phải tự tạo tế bào mới từ môi trường."],"ans":0,"exp":"<i>E. coli</i> ưu tiên dùng Glucose (hiệu quả năng lượng cao nhất) và ức chế dị hóa Operon Lac khi còn Glucose; khi hết Glucose cần thời gian ngắn cảm ứng tổng hợp $\\beta$-galactosidase và permease."},{"id":"MCQ-CB-135","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Vi sinh vật","q":"Một chủng vi khuẩn phát triển tối ưu ở môi trường có nhiệt độ $85^\\circ\\text{C}$ (ưa siêu nhiệt) như <i>Thermus aquaticus</i> hoặc cổ khuẩn <i>Pyrolobus fumarii</i>. Đặc điểm thích nghi cấu trúc phân tử nào giúp màng sinh chất và enzyme của chúng không bị tan chảy hay biến tính ở nhiệt độ sôi?","opts":["Màng sinh chất giàu acid béo bão hòa chuỗi dài hoặc lớp đơn lipid cầu nối ether (ở Archaea), còn protein có lõi kỵ nước dày đặc hơn, nhiều cầu muối ion và cầu disulfide ổn định nhiệt.","Tế bào chất của chúng chứa 90% đường Fructose lỏng.","DNA của chúng chỉ gồm 100% các cặp $A-T$ và không chứa liên kết phosphodiester.","Màng sinh chất chỉ toàn acid béo không no nối đôi <i>cis</i>."],"ans":0,"exp":"Vi khuẩn/cổ khuẩn ưa nhiệt tối ưu hóa tính bền nhiệt bằng liên kết ether đơn lớp (tetraether ở Archaea), tỷ lệ $G-C$ cao trong rRNA/tRNA và tăng mật độ cầu muối, tương tác kỵ nước trong lõi enzyme (như Taq polymerase)."},{"id":"MCQ-CB-136","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Vi sinh vật","q":"Trong phương pháp xác định số lượng tế bào vi khuẩn sống (Viable cell count) bằng cách pha loãng bậc 10 liên tiếp mẫu nước hồ rồi trải $0.1\\text{ ml}$ dung dịch ở độ pha loãng $10^{-5}$ lên đĩa thạch dinh dưỡng, người ta đếm được trung bình $45$ khuẩn lạc mọc lên sau 24 giờ ủ. Mật độ vi khuẩn sống trong $1\\text{ ml}$ mẫu nước hồ ban đầu là bao nhiêu?","opts":["$4.5 \\times 10^5\\text{ CFU/ml}$.","$4.5 \\times 10^7\\text{ CFU/ml}$.","$4.5 \\times 10^8\\text{ CFU/ml}$.","$4.5 \\times 10^6\\text{ CFU/ml}$."],"ans":1,"exp":"Mật độ $= \\frac{\\text{Số khuẩn lạc}}{\\text{Thể tích trải} \\times \\text{Hệ số pha loãng}} = \\frac{45}{0.1 \\times 10^{-5}} = 45 \\times 10^6 = 4.5 \\times 10^7\\text{ CFU/ml}$."},{"id":"MCQ-CB-137","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Vi sinh vật","q":"Cơ chế truyền vật chất di truyền theo chiều ngang ở vi khuẩn mà trong đó một đoạn DNA trần từ tế bào chết bị vỡ được tế bào vi khuẩn sống trực tiếp hấp thụ từ môi trường và tái tổ hợp vào hệ gen của nó (như thí nghiệm Griffith trên phế cầu khuẩn) được gọi là gì?","opts":["Tiếp hợp (Conjugation - qua lông nhung giới tính F).","Tải nạp (Transduction - qua trung gian thể thực khuẩn).","Biến nạp (Transformation).","Phiên mã ngược."],"ans":2,"exp":"Biến nạp (Transformation) là sự thu nhận DNA ngoại lai tự do từ môi trường vào tế bào khả biến; Tải nạp nhờ phage; Tiếp hợp qua tiếp xúc trực tiếp cầu F-pilus."},{"id":"MCQ-CB-138","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Virus & Thực vật","q":"Bệnh đỉnh chùm khoai tây (Potato spindle tuber) không phải do virus hoàn chỉnh gây ra mà do tác nhân Viroid. Cấu trúc của tác nhân Viroid là gì?","opts":["Một phân tử DNA mạch kép dài hơn $100\\text{ kb}$.","Chỉ là một phân tử protein gấp cuộn sai hoàn toàn không có axit nucleic.","Chỉ là một phân tử RNA mạch đơn vòng cực nhỏ (khoảng $250-400$ nucleotide), KHÔNG có vỏ protein capsid và cũng không mã hóa bất kỳ protein nào.","Một vi khuẩn cộng sinh ký sinh trong mạch rây."],"ans":2,"exp":"Viroid là tác nhân gây bệnh thực vật nhỏ nhất được biết: RNA vòng trần bắt cặp nội phân tử dạng que, tự nhân bản nhờ RNA polymerase II của cây chủ và gây bệnh qua cơ chế can thiệp RNA (RNAi)."},{"id":"MCQ-CB-139","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cấu trúc tế bào","q":"Trong tế bào biểu mô ống thận hoặc tế bào biểu mô ruột non có vi nhung mao (microvilli), lõi nâng đỡ bên trong mỗi vi nhung mao và cơ chế neo giữ hình dạng ngón tay giúp tăng diện tích hấp thụ là loại sợi khung xương tế bào nào?","opts":["Các bó vi sợi Actin song song liên kết chéo với nhau bởi các protein như Villin và Fimbrin.","Lớp thành Cellulose bên ngoài màng sinh chất.","Các sợi trung gian Keratin chạy xuyên qua hai màng tế bào.","Hệ thống ống rỗng vi ống xuất phát từ trung thể."],"ans":0,"exp":"Vi nhung mao (bờ bàn chải) được nâng đỡ bởi lõi bó vi sợi Actin; khác với lông chuyển (cilia) và roi (flagella) có cấu trúc vi ống $9+2$ trượt nhờ Dynein."},{"id":"MCQ-CB-140","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cấu trúc tế bào","q":"Một bệnh nhân nam bị đồng thời cả nhiễm trùng đường hô hấp mãn tính (viêm xoang, giãn phế quản do ứ đọng dịch nhầy), vô sinh do tinh trùng bất động hoàn toàn và đảo ngược phủ tạng (Hội chứng Kartagener). Bất thường phân tử nào giải thích được cả 3 triệu chứng trên?","opts":["Đột biến hỏng bơm $Na^+/K^+$-ATPase.","Đột biến mất protein động cơ Dynein (cánh tay dynein) ở vi ống của lông chuyển biểu mô khí quản, roi tinh trùng và lông chuyển nút phôi.","Thiếu hụt vi sợi Actin ở tế bào cơ tim.","Thiếu enzyme Catalase trong Peroxisome."],"ans":1,"exp":"Lông chuyển (cilia) đường hô hấp, lông chuyển xác định trục trái-phải ở phôi và đuôi tinh trùng đều có cấu trúc trục sợi trục (axoneme) $9+2$ vận động nhờ Dynein sử dụng ATP."},{"id":"MCQ-CB-141","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Apoptosis","q":"Trong quá trình kiểm soát Apoptosis nội sinh ở động vật có vú, vai trò đối kháng giữa họ protein $Bcl-2$ (chống apoptosis) và $Bax/Bak$ (thúc đẩy apoptosis) diễn ra tại màng bào quan nào?","opts":["Màng nhân trong.","Màng ngoài của Ti thể (Bax/Bak tạo kênh làm thoát Cytochrome c; Bcl-2 ngăn cản quá trình này).","Màng lưới nội chất trơn.","Màng trong của Lục lạp."],"ans":1,"exp":"Protein họ Bcl-2 điều phối tính thấm màng ngoài ti thể (MOMP): khi tín hiệu tổn thương DNA kích hoạt $p53$, protein $Bax/Bak$ tạo lỗ trên màng ngoài ti thể giải phóng Cytochrome c kích hoạt Caspase-9."},{"id":"MCQ-CB-142","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Truyền tin & Tế bào","q":"Trong kỹ thuật lai tế bào và theo dõi sự vận chuyển protein qua màng, chất kháng sinh Brefeldin A ngăn cản quá trình hình thành túi vận chuyển có áo COPI (vận chuyển ngược từ Golgi về ER) và làm sáp nhập ngược bộ máy Golgi vào mạng lưới ER. Nếu tế bào bị xử lý Brefeldin A, điều gì xảy ra với các protein tiết bình thường đi qua đường ER $\\rightarrow$ Golgi?","opts":["Protein tiết được bơm thẳng qua màng nhân ra ngoài.","Ribosome 80S ngừng tổng hợp protein ngay lập tức.","Tốc độ xuất bào tăng gấp 3 lần do bỏ qua Golgi.","Quá trình xuất bào protein tiết bị đình trệ hoàn toàn vì cấu trúc bộ máy Golgi bị phá vỡ tan biến trở về ER."],"ans":3,"exp":"Brefeldin A ức chế yếu tố trao đổi GTP của Arf1, làm rối loạn cân bằng vận chuyển màng giữa ER và Golgi dẫn đến tan rã bộ máy Golgi và chặn đứng con đường xuất bào."},{"id":"MCQ-CB-143","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thẩm thấu & Màng","q":"Một tế bào thực vật có áp suất thẩm thấu của dịch bào (ở điều kiện cân bằng trương nước) với thế chất tan $\\Psi_s = -0.8\\text{ MPa}$ được đặt vào dung dịch đường có thế nước $\\Psi_w = -0.8\\text{ MPa}$. Nếu đo ngay lúc tế bào vừa mới chớm co nguyên sinh (tại điểm $\\Psi_p = 0$), thế nước của tế bào khi đó là bao nhiêu?","opts":["$\\Psi_w = -0.8\\text{ MPa}$ (tại điểm bắt đầu co nguyên sinh, $\\Psi_p = 0$ nên $\\Psi_w = \\Psi_s$).","$\\Psi_w = +0.8\\text{ MPa}$.","$\\Psi_w = 0\\text{ MPa}$.","$\\Psi_w = -1.6\\text{ MPa}$."],"ans":0,"exp":"Áp dụng $\\Psi_w = \\Psi_s + \\Psi_p$. Tại điểm chớm co nguyên sinh (Incipient plasmolysis), màng vừa tách nhẹ khỏi thành nên áp suất trương $\\Psi_p = 0$, do đó $\\Psi_w = \\Psi_s = -0.8\\text{ MPa}$."},{"id":"MCQ-CB-144","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Enzyme & pH","q":"Sự thay đổi độ pH quá lệch khỏi pH tối ưu thường làm mất hoạt tính xúc tác của enzyme trước cả khi gây phá vỡ cấu trúc toàn phần. Nguyên nhân phân tử trực tiếp nhất của sự giảm hoạt tính nhẹ và vừa khi đổi pH là gì?","opts":["Chuyển hóa enzyme thành lipid trung tính.","Sự thay đổi trạng thái ion hóa (nhận hoặc mất proton $H^+$) của các gốc amino acid mang điện ở trung tâm hoạt động và ở cơ chất, làm phá vỡ khả năng gắn cơ chất hoặc bước xúc tác acid-base.","Làm thay đổi trình tự amino acid mã hóa trong DNA.","Phá hủy ngay các liên kết cộng hóa trị peptide dọc khung chính."],"ans":1,"exp":"Trung tâm hoạt động thường chứa các gốc His, Asp, Glu, Lys đòi hỏi trạng thái proton hóa chính xác để gắn cơ chất và nhường/nhận $H^+$ trong xúc tác."},{"id":"MCQ-CB-145","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hô hấp tế bào","q":"Tại sao khi một vận động viên chạy marathon tiêu thụ hết lượng glycogen dự trữ và chuyển sang sử dụng chủ yếu lipid dự trữ, chỉ số thương số hô hấp ($RQ = \\text{CO}_2\\text{ thải} / \\text{O}_2\\text{ nhận}$) giảm từ khoảng $1.0$ xuống gần $0.7$?","opts":["Vì phổi ngừng thải $CO_2$ khi chạy đường dài.","Vì phân giải lipid không hề tạo ra $CO_2$.","Vì phân tử acid béo nghèo oxy hơn nhiều so với carbohydrate nên cần tiêu tốn lượng $O_2$ lớn hơn nhiều để oxy hóa thành $CO_2$ và $H_2O$ (ví dụ Palmitate $C_{16}H_{32}O_2 + 23O_2 \\rightarrow 16CO_2 + 16H_2O \\Rightarrow RQ = 16/23 \\approx 0.70$).","Vì acid béo chỉ lên men tạo acid lactic với $RQ = 0.7$."],"ans":2,"exp":"Hydrocarbon trong acid béo ở trạng thái khử cao (ít nguyên tử O nội tại) nên đòi hỏi hệ số $O_2$ cao hơn hệ số $CO_2$ sinh ra."},{"id":"MCQ-CB-146","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hô hấp tế bào","q":"Ở bước 6 của Chu trình Krebs (chuyển Succinate thành Fumarate nhờ enzyme Succinate dehydrogenase), điểm đặc biệt về vị trí và coenzyme của enzyme này khác với toàn bộ các enzyme khác trong chu trình Krebs là gì?","opts":["Enzyme này nằm tự do trong bào tương và tạo ra GTP.","Enzyme này giải phóng cùng lúc 3 phân tử $CO_2$.","Succinate dehydrogenase nằm gắn chặt ngay trên màng trong ti thể (chính là Phức hợp II của chuỗi truyền $e^-$) và sử dụng $FAD$ tạo $FADH_2$ thay vì $NAD^+$ ở chất nền.","Enzyme này sử dụng ánh sáng để tổng hợp ATP."],"ans":2,"exp":"Trong 8 enzyme của chu trình Krebs, 7 enzyme tan tự do trong chất nền ti thể, duy nhất Succinate dehydrogenase gắn xuyên màng trong ti thể đóng vai trò Phức hợp II."},{"id":"MCQ-CB-147","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quang hợp & Bào quan","q":"Khi ủ lục lạp trong tối sau khi đã chiếu sáng trước một thời gian trong môi trường KHÔNG có $CO_2$, rồi mới tắt đèn và sục $CO_2$ đánh dấu phóng xạ ($^{14}\\text{CO}_2$) vào trong tối, quá trình cố định $^{14}\\text{CO}_2$ vẫn diễn ra trong thời gian ngắn rồi dừng lại. Tại sao?","opts":["Nhờ lượng $ATP$ và $NADPH$ đã tích lũy sẵn trong pha sáng trước đó giúp chu trình Calvin cố định $^{14}\\text{CO}_2$ trong tối cho đến khi hai chất này cạn kiệt.","Vì enzyme RuBisCO tự phát sáng thay ánh sáng mặt trời.","Vì ti thể tự động chuyển $CO_2$ thành tinh bột.","Vì chu trình Calvin không cần sử dụng $ATP$ và $NADPH$."],"ans":0,"exp":"Thí nghiệm kinh điển chứng minh pha tối (chu trình Calvin) không trực tiếp cần ánh sáng nhưng phụ thuộc hoàn toàn vào nguồn sản phẩm $ATP$ và $NADPH$ từ pha sáng."},{"id":"MCQ-CB-148","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Vi sinh vật","q":"Trong kỹ thuật nuôi cấy liên tục (Chemostat) dùng để thu sinh khối vi sinh vật làm protein đơn bào ở quy mô công nghiệp, dòng dịch dinh dưỡng mới được bơm vào và dòng dịch nuôi cũ (chứa tế bào và chất thải) được rút ra liên tục với tốc độ bằng nhau. Ở trạng thái ổn định (Steady state), quần thể vi khuẩn luôn được duy trì ở pha nào?","opts":["Pha lũy thừa (Log phase) với tốc độ sinh trưởng riêng bằng tốc độ pha loãng ($\\mu = D$).","Pha suy vong.","Pha tiềm phát (Lag phase) kéo dài vô hạn.","Pha bào tử hóa bất hoạt."],"ans":0,"exp":"Nuôi cấy liên tục giữ ổn định nồng độ chất dinh dưỡng giới hạn và loại bỏ chất độc, giúp vi sinh vật sinh trưởng không ngừng ở pha lũy thừa."},{"id":"MCQ-CB-149","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Virus","q":"Tại sao virus thực vật (như virus khảm thuốc lá TMV) thường không cần cơ chế gắn thụ thể màng đặc hiệu như virus động vật, mà lại lây lan rất nhanh từ tế bào này sang tế bào khác trong cùng một cây sau khi đã xâm nhập qua vết thương cơ học?","opts":["Vì tế bào thực vật không có thành tế bào bảo vệ.","Vì virus thực vật mã hóa 'protein di chuyển' (Movement protein) làm giãn rộng cầu sinh chất (Plasmodesmata) để truyền trực tiếp axit nucleic/virion sang tế bào kế cận mà không cần ra khỏi thành cellulose.","Vì côn trùng chui thẳng vào bên trong từng tế bào lá.","Vì virus thực vật thực bào qua màng tế bào thực vật."],"ans":1,"exp":"Do tế bào thực vật có thành cellulose cứng, virus cần vết trầy xước (côn trùng chích hút, cơ học) để vào tế bào đầu tiên, sau đó lan toàn thân qua cầu sinh chất và mạch rây."},{"id":"MCQ-CB-150","topic":"cellbio","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hóa sinh màng","q":"Bơm $H^+$/V-ATPase trên màng Lysosome và màng Không bào thực vật hoạt động tương tự phần $F_0 F_1$ của ti thể nhưng chạy theo chiều NGƯỢC lại. Quá trình này thực hiện biến đổi năng lượng nào?","opts":["Sử dụng gradient $H^+$ từ trong Lysosome ra ngoài để tổng hợp ATP.","Tạo khí $O_2$ trong Lysosome.","Thủy phân ATP để bơm chủ động ion $H^+$ ngược chiều nồng độ vào bên trong lòng Lysosome/Không bào, tạo môi trường acid ($pH \\approx 4.5 - 5.0$).","Bơm $Na^+$ vào Lysosome và đẩy $H^+$ ra ngoài."],"ans":2,"exp":"V-ATPase (Vacuolar-type $H^+$-ATPase) sử dụng năng lượng thủy phân ATP để axit hóa khoang nội bào (Lysosome, thể nội bào, không bào thực vật, hủy cốt bào)."}];
